)

const PreviewByteLimit = 32 * 1024

type ReadOnlyUseCases interface {
	Dashboard(ctx context.Context) (DashboardResult, error)
	PreviewArtifact(ctx context.Context, path string) (ArtifactPreviewResult, error)
}

type DashboardResult struct {
	Workspace string
	Projects  []ProjectSummary
	Studies   []StudySummary
	Sprints   []SprintSummary
}

type DisplayFinding struct {
	Severity   string
	Section    string
	Path       string
	Problem    string
	Cause      string
	Suggestion string
}

type DisplayArtifact struct {
	Label string
	Path  string
	Kind  string
}

type ArtifactPreviewResult struct {
	Path      string
	Kind      string
	Content   string
	Truncated bool
	Missing   bool
	Invalid   bool
	Error     string
}

type dashboardUseCases struct {
	root              string
	runner            func(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error)
	stageRuntime      map[sprint.PlanningStage]sprint.StageRuntime
	reviewConcurrency int
	smokeSettings     sprint.SmokeSettings
	qaSettings        sprint.QASettings
	readOnly          bool
	runs              RunUseCases
	durable           DurableOperationManager
}

func (u dashboardUseCases) Runs(ctx context.Context, query RunQuery) (RunPage, error) {
	if u.runs == nil {
		return RunPage{}, ErrWebUnavailable
	}
	return u.runs.Runs(ctx, query)
}
func (u dashboardUseCases) Run(ctx context.Context, id RunID) (RunSnapshot, error) {
	if u.runs == nil {
		return RunSnapshot{}, ErrWebUnavailable
	}
	return u.runs.Run(ctx, id)
}
func (u dashboardUseCases) RunEvents(ctx context.Context, id RunID, after uint64, limit int) ([]RunEvent, error) {
	if u.runs == nil {
		return nil, ErrWebUnavailable
	}
	return u.runs.RunEvents(ctx, id, after, limit)
}
func (u dashboardUseCases) CancelRun(ctx context.Context, id RunID, reason string) (RunSnapshot, bool, error) {
	if u.runs == nil {
		return RunSnapshot{}, false, ErrWebUnavailable
	}
	return u.runs.CancelRun(ctx, id, reason)
}
func (u dashboardUseCases) RunHealth(ctx context.Context) (RunHealthResult, error) {
	if u.runs == nil {
		return RunHealthResult{}, ErrWebUnavailable
	}
	return u.runs.RunHealth(ctx)
}
func (u dashboardUseCases) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	if u.durable == nil {
		return AcceptedOperation{}, ErrWebUnavailable
	}
	return u.durable.AcceptOperation(ctx, confirmation, digest)
}
func (u dashboardUseCases) RecordOperationEvent(ctx context.Context, id string, event OperationEvent) (bool, error) {
	if u.durable == nil {
		return false, ErrWebUnavailable
	}
	return u.durable.RecordOperationEvent(ctx, id, event)
}
func (u dashboardUseCases) FinishOperation(ctx context.Context, id string, state OperationState, err error) error {
	if u.durable == nil {
		return ErrWebUnavailable
	}
	return u.durable.FinishOperation(ctx, id, state, err)
}

func (u dashboardUseCases) sprintService() sprint.Service {
	service := sprint.NewService(u.root).WithStageRuntime(u.stageRuntime).WithReviewConcurrency(u.reviewConcurrency)
	if u.qaSettings.Runtime.Model != "" {
		service = service.WithQASettings(u.qaSettings)
	}
	if u.smokeSettings.DiscoveryTimeout > 0 {
		service = service.WithSmokeSettings(u.smokeSettings)
	}
	if u.readOnly {
		service = service.WithoutStatusWrites()
	}
	return service
}

func NewReadOnlyUseCases(root string) ReadOnlyUseCases {
	return dashboardUseCases{root: root}
}

func (u dashboardUseCases) Dashboard(ctx context.Context) (DashboardResult, error) {
	if err := ctx.Err(); err != nil {
		return DashboardResult{}, err
	}
	projects, err := u.ProjectSummaries(ctx)
	if err != nil {
		return DashboardResult{}, err
	}
	studies, err := u.StudySummaries(ctx)
	if err != nil {
		return DashboardResult{}, err
	}
	sprints, err := u.SprintSummaries(ctx)
	if err != nil {
		return DashboardResult{}, err
	}
	return DashboardResult{Workspace: u.root, Projects: projects, Studies: studies, Sprints: sprints}, nil
}

func (u dashboardUseCases) PreviewArtifact(ctx context.Context, rel string) (ArtifactPreviewResult, error) {
	if err := ctx.Err(); err != nil {
		return ArtifactPreviewResult{}, err
	}
	rel = filepath.ToSlash(filepath.Clean(filepath.FromSlash(strings.TrimSpace(rel))))
	if !supportedPreviewPath(rel) {
		return ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Error: "unsupported artifact path"}, nil
	}
	path, err := workspace.ResolveInside(u.root, rel)
	if err != nil {
		return ArtifactPreviewResult{Path: rel, Error: err.Error()}, nil
	}
	if err := rejectPreviewSymlink(u.root, rel); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Error: "artifact path contains a symbolic link"}, nil
	}
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Missing: true, Error: "artifact is missing"}, nil
		}
		return ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Error: fmt.Sprintf("read artifact: %v", err)}, nil
	}
	defer f.Close()
	limited := io.LimitReader(f, PreviewByteLimit+1)
	data, err := io.ReadAll(limited)
	if err != nil {
		return ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Error: fmt.Sprintf("read artifact: %v", err)}, nil
	}
	truncated := len(data) > PreviewByteLimit
	if truncated {
		data = data[:PreviewByteLimit]
	}
	result := ArtifactPreviewResult{Path: rel, Kind: previewKind(rel), Content: string(data), Truncated: truncated}
	if result.Kind == "json" && json.Valid(data) == false {
		result.Invalid = true
		result.Error = "invalid JSON preview"
	}
	return result, nil
}

func rejectPreviewSymlink(root, rel string) error {
	path := root
	for _, part := range strings.Split(filepath.Clean(filepath.FromSlash(rel)), string(filepath.Separator)) {
		path = filepath.Join(path, part)
		info, err := os.Lstat(path)
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("symbolic link component: %s", part)
		}
	}
	return nil
}

func supportedPreviewPath(rel string) bool {
	if rel == "." || rel == ".." || strings.HasPrefix(rel, "../") || filepath.IsAbs(rel) {
		return false
	}
	base := filepath.Base(rel)
	if base == "project-index.md" || base == "roadmap.md" || base == "requirements.md" || base == "code-context.md" || base == "sprint-index.md" ||
		base == "technical-handbook.md" || base == "reasoning.md" || base == "plan.md" || base == "execute.md" || base == "review.md" || base == "smoke.md" ||
		base == "flow-state.json" || base == ".run-state.json" {
		return true
	}
	if strings.HasPrefix(rel, "projects/") && strings.Contains(rel, "/docs/") && strings.HasSuffix(rel, ".md") {
		return true
	}
	if strings.HasPrefix(rel, "studies/") {
		if strings.Contains(rel, "/dimensions/") && strings.HasSuffix(rel, ".md") {
			return true
		}
		if strings.Contains(rel, "/sources/") && strings.HasSuffix(rel, ".md") {
			return true
		}
		if strings.Contains(rel, "/reports/") && strings.HasSuffix(rel, ".md") {
			return true
		}
		if strings.HasSuffix(rel, "/.ultraplan/run-state.json") {
			return true
		}
	}
	return false
}

func previewKind(rel string) string {
	if strings.HasSuffix(rel, ".json") {
		return "json"
	}
	return "markdown"
}

func displaySafe(value string) string {
	value = config.RedactValue("tui.display", value)
	var b strings.Builder
	b.Grow(len(value))
	for i := 0; i < len(value); {
		if value[i] == 0x1b {
			i++
			if i < len(value) && value[i] == '[' {
				i++
				for i < len(value) {
					terminal := value[i] >= 0x40 && value[i] <= 0x7e
					i++
					if terminal {
						break
					}
				}
			}
			continue
		}
		if value[i] < 0x20 && value[i] != '\n' && value[i] != '\t' {
			i++
			continue
		}
		b.WriteByte(value[i])
		i++
	}
	return b.String()
}

func sortArtifacts(items []DisplayArtifact) {
	sort.Slice(items, func(i, j int) bool {
		if items[i].Path == items[j].Path {
			return items[i].Label < items[j].Label
		}
		return items[i].Path < items[j].Path
	})
}

func projectFinding(f project.ValidationFinding) DisplayFinding {
	return DisplayFinding{
		Severity:   string(f.Severity),
		Section:    string(f.Section),
		Path:       f.Path,
		Problem:    displaySafe(f.Problem),
		Cause:      displaySafe(f.Cause),
		Suggestion: displaySafe(f.Suggestion),
	}
}

func sprintFinding(f sprint.ValidationFinding) DisplayFinding {
	return DisplayFinding{
		Severity:   "error",
		Section:    f.Section,
		Path:       f.Path,
		Problem:    displaySafe(f.Problem),
		Cause:      displaySafe(f.Cause),
		Suggestion: displaySafe(f.Suggestion),
	}
}

func studyFinding(c study.ValidationCheck) DisplayFinding {
	return DisplayFinding{
		Severity:   string(c.Severity),
		Section:    c.Name,
		Path:       c.Path,
		Problem:    displaySafe(string(c.Status)),
		Cause:      displaySafe(c.Observed),
		Suggestion: displaySafe(c.Guidance),
	}
}

package tui

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"strconv"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
	tea "github.com/charmbracelet/bubbletea"
)

type Options struct {
	UseCases app.OperationalUseCases
	Stdout   io.Writer
	Width    int
}

func Run(ctx context.Context, opts Options) error {
	if opts.UseCases == nil {
		return fmt.Errorf("tui: missing read-only use cases")
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	program := tea.NewProgram(newTeaModel(ctx, opts.UseCases, opts.Width), tea.WithAltScreen(), tea.WithOutput(opts.Stdout))
	_, err := program.Run()
	return err
}

type teaModel struct {
	ctx         context.Context
	model       Model
	width       int
	height      int
	cancel      context.CancelFunc
	eventStream <-chan app.OperationEvent
}
type runViewTickMsg struct{}

func newTeaModel(ctx context.Context, useCases app.OperationalUseCases, width int) teaModel {
	if width <= 0 {
		width = 100
	}
	return teaModel{ctx: ctx, model: NewModel(useCases), width: width, height: 40}
}

func (m teaModel) Init() tea.Cmd {
	return m.loadCmd()
}

func (m teaModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch v := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = v.Width
		m.height = v.Height
		return m, nil
	case tea.KeyMsg:
		if m.model.ParallelForm != nil {
			switch v.String() {
			case "esc":
				m.model.ParallelForm = nil
				m.model.ParallelValue = ""
				m.model.ParallelError = ""
				return m, nil
			case "backspace":
				if len(m.model.ParallelValue) > 0 {
					m.model.ParallelValue = m.model.ParallelValue[:len(m.model.ParallelValue)-1]
				}
				m.model.ParallelError = ""
				return m, nil
			case "enter":
				value := 3
				if m.model.ParallelValue != "" {
					parsed, err := strconv.Atoi(m.model.ParallelValue)
					if err != nil || parsed < 1 || parsed > 64 {
						m.model.ParallelError = "parallelism must be between 1 and 64"
						return m, nil
					}
					value = parsed
				}
				req := *m.model.ParallelForm
				req.Parallelism = value
				m.model.ParallelForm = nil
				m.model.ParallelValue = ""
				m.model.Loading = true
				return m, m.confirmationCmd(req)
			default:
				if len(v.Runes) == 1 && v.Runes[0] >= '0' && v.Runes[0] <= '9' {
					m.model.ParallelValue += string(v.Runes[0])
					m.model.ParallelError = ""
				}
				return m, nil
			}
		}
		action := KeyToAction(v.String())
		switch action {
		case ActionConfirm:
			if m.model.Confirmation != nil && !m.model.Running {
				return m.beginOperation(m.model.Confirmation.Request)
			}
			return m, nil
		case ActionCancel:
			if m.model.Running && m.model.ActiveRunID != "" {
				if runs, ok := m.model.UseCases.(app.RunUseCases); ok {
					if _, _, err := runs.CancelRun(m.ctx, app.RunID(m.model.ActiveRunID), "user_requested"); err != nil {
						m.model.Error = err.Error()
					} else if m.model.Operation != nil {
						m.model.Operation.Message = "durable cancellation requested; waiting for owner acknowledgement"
					}
					return m, nil
				}
			}
			if m.model.Running && m.cancel != nil {
				m.cancel()
				return m, nil
			}
			if route := m.model.currentRoute(); route.Kind == RouteRun && route.RunID != "" {
				if runs, ok := m.model.UseCases.(app.RunUseCases); ok {
					if _, _, err := runs.CancelRun(m.ctx, app.RunID(route.RunID), "user_requested"); err != nil {
						m.model.Error = err.Error()
					} else {
						m.model.Error = "durable cancellation requested"
					}
					return m, m.refreshCmd()
				}
			}
			study := m.model.RunViewStudy
			if study == "" {
				if item, ok := m.model.selectedItem(); ok {
					study = item.ViewRun
				}
			}
			if study != "" && !m.model.Running {
				return m.beginOperation(app.OperationRequest{Kind: app.OperationStudyCancel, Study: study})
			}
			return m, nil
		case ActionQuit:
			if m.model.Running {
				m.model.OperationHidden = true
				m.model.Error = "active durable work was not cancelled; press c to request cancellation or reopen its run"
				return m, nil
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, tea.Quit
		case ActionRefresh:
			m.model.Loading = true
			return m, m.refreshCmd()
		case ActionOpen:
			if m.model.Confirmation != nil && !m.model.Running {
				return m.beginOperation(m.model.Confirmation.Request)
			}
			if m.model.RunViewStudy != "" {
				m.model.RunViewShowPrevious = !m.model.RunViewShowPrevious
				return m, nil
			}
			if m.model.Running && !m.model.OperationHidden && (m.model.ActiveOperation.Kind == app.OperationStudyStart || m.model.ActiveOperation.Kind == app.OperationStudyResume) {
				m.model.OperationShowPrevious = !m.model.OperationShowPrevious
				return m, nil
			}
			if item, ok := m.model.selectedItem(); ok && item.ViewRun != "" && m.model.Focus == FocusContent {
				m.model.RunViewStudy = item.ViewRun
				m.model.RunViewShowPrevious = false
				return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
			}
			if item, ok := m.model.selectedItem(); ok && item.Validation != nil && m.model.Focus == FocusContent && m.model.Preview == nil {
				m.model.Loading = true
				return m, m.validationCmd(*item.Validation)
			}
			if item, ok := m.model.selectedItem(); ok && item.Operation != nil && m.model.Focus == FocusContent {
				if item.Operation.Kind == app.OperationStudyResume || item.Operation.Kind == app.OperationStudyStart {
					req := *item.Operation
					m.model.ParallelForm = &req
					m.model.ParallelValue = ""
					m.model.ParallelError = ""
					return m, nil
				}
				m.model.Loading = true
				return m, m.confirmationCmd(*item.Operation)
			}
			if item, ok := m.model.selectedItem(); ok && item.Path != "" && m.model.Focus == FocusContent && m.model.Preview == nil {
				return m, m.previewCmd()
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			if m.model.currentRoute().Kind == RouteRun {
				return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
			}
			return m, nil
		case ActionBack, ActionFocusNext, ActionLeft, ActionRight:
			if action == ActionBack && m.model.Running && !m.model.OperationHidden && (m.model.ActiveOperation.Kind == app.OperationStudyStart || m.model.ActiveOperation.Kind == app.OperationStudyResume) {
				m.model.OperationHidden = true
				m.model.OperationShowPrevious = false
				return m, m.refreshCmd()
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		case ActionClosePreview:
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		default:
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		}
	case OperationMsg:
		m.model = m.model.Update(v)
		m.cancel = nil
		m.eventStream = nil
		return m, m.refreshCmd()
	case OperationEventMsg:
		m.model = m.model.Update(v)
		if m.eventStream != nil && m.model.Running {
			return m, waitOperationEvent(m.eventStream)
		}
		return m, nil
	case LoadMsg, RefreshMsg, PreviewMsg, ValidationMsg, ConfirmationMsg:
		m.model = m.model.Update(v)
		return m, nil
	case runViewTickMsg:
		if m.model.RunViewStudy != "" || m.model.currentRoute().Kind == RouteRun {
			return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
		}
		return m, nil
	default:
		return m, nil
	}
}

func (m teaModel) beginOperation(req app.OperationRequest) (tea.Model, tea.Cmd) {
	opctx, cancel := context.WithCancel(m.ctx)
	acceptedRunID := ""
	if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && m.model.Confirmation != nil {
		basis := m.model.Confirmation.CanonicalRequest + "\x00" + m.model.Confirmation.InputFingerprint
		digest := sha256.Sum256([]byte(basis))
		accepted, err := manager.AcceptOperation(opctx, *m.model.Confirmation, hex.EncodeToString(digest[:]))
		if err != nil {
			cancel()
			m.model.Error = err.Error()
			m.model.Loading = false
			return m, nil
		}
		if accepted.Existing {
			cancel()
			m.model.Operation = &app.OperationResult{State: app.OperationState(accepted.Lifecycle), RunID: accepted.RunID, Message: "matching durable operation already exists"}
			m.model.Confirmation = nil
			return m, nil
		}
		acceptedRunID = accepted.RunID
		if accepted.Context != nil {
			opctx = accepted.Context
		}
	}
	m.cancel = cancel
	m.model.Running = true
	m.model.Events = nil
	m.model.Confirmation = nil
	m.model.RunViewStudy = ""
	m.model.ActiveOperation = req
	m.model.OperationShowPrevious = false
	m.model.OperationHidden = false
	m.model.ActiveRunID = acceptedRunID
	m.model.Operation = &app.OperationResult{State: app.OperationRunning, RunID: acceptedRunID, Subject: operationSubject(req), Message: "operation running; c requests durable cancellation; q keeps the run active"}
	stream := make(chan app.OperationEvent, 128)
	m.eventStream = stream
	return m, tea.Batch(m.operationCmd(opctx, req, acceptedRunID, stream), waitOperationEvent(stream))
}

func runViewTickCmd() tea.Cmd {
	return tea.Tick(time.Second, func(time.Time) tea.Msg { return runViewTickMsg{} })
}

func (m teaModel) confirmationCmd(req app.OperationRequest) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		r, e := m.model.UseCases.PrepareOperation(m.ctx, req)
		return ConfirmationMsg{Result: r, Err: e, Route: route}
	}
}
func (m teaModel) operationCmd(ctx context.Context, req app.OperationRequest, runID string, stream chan app.OperationEvent) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		defer close(stream)
		r, e := m.model.UseCases.RunOperation(ctx, req, func(event app.OperationEvent) {
			if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && runID != "" {
				committed, err := manager.RecordOperationEvent(context.Background(), runID, event)
				if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
					return
				}
				if err == nil && !committed {
					return
				}
			}
			select {
			case stream <- event:
			default:
			}
		})
		r.RunID = runID
		if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && runID != "" {
			finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			finishErr := manager.FinishOperation(finishCtx, runID, r.State, e)
			cancel()
			if finishErr != nil {
				e = errors.Join(e, finishErr)
			}
		}
		return OperationMsg{Result: r, Err: e, Route: route}
	}
}

func waitOperationEvent(stream <-chan app.OperationEvent) tea.Cmd {
	return func() tea.Msg {
		event, ok := <-stream
		if !ok {
			return nil
		}
		return OperationEventMsg{Event: event}
	}
}

func operationSubject(req app.OperationRequest) string {
	if req.Study != "" {
		return req.Study
	}
	return req.Project + "/" + req.Sprint
}

func (m teaModel) validationCmd(req app.ValidationRequest) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		result, err := m.model.UseCases.Validate(m.ctx, req)
		return ValidationMsg{Result: result, Err: err, Route: route}
	}
}

func (m teaModel) View() string {
	return RenderWithSize(m.model, m.width, m.height)
}

func (m teaModel) loadCmd() tea.Cmd {
	return func() tea.Msg {
		result, runs, events, err := m.dashboardAndRuns()
		return LoadMsg{Result: result, Runs: runs, Events: events, Err: err}
	}
}

func (m teaModel) refreshCmd() tea.Cmd {
	return func() tea.Msg {
		result, runs, events, err := m.dashboardAndRuns()
		return RefreshMsg{Result: result, Runs: runs, Events: events, Err: err}
	}
}

func (m teaModel) dashboardAndRuns() (app.DashboardResult, []app.RunSnapshot, []app.RunEvent, error) {
	result, err := m.model.UseCases.Dashboard(m.ctx)
	if err != nil {
		return result, nil, nil, err
	}
	runsCapability, ok := m.model.UseCases.(app.RunUseCases)
	if !ok {
		return result, nil, nil, nil
	}
	page, err := runsCapability.Runs(m.ctx, app.RunQuery{Limit: 200})
	if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
		return result, nil, nil, err
	}
	var events []app.RunEvent
	route := m.model.currentRoute()
	if route.Kind == RouteRun && route.RunID != "" {
		for _, snapshot := range page.Runs {
			if string(snapshot.RunID) != route.RunID {
				continue
			}
			after := uint64(0)
			if snapshot.OldestRetainedSequence > 1 {
				after = snapshot.OldestRetainedSequence - 1
			}
			events, err = runsCapability.RunEvents(m.ctx, snapshot.RunID, after, 200)
			if err != nil {
				return result, page.Runs, nil, err
			}
			break
		}
	}
	return result, page.Runs, events, nil
}

func (m teaModel) previewCmd() tea.Cmd {
	return func() tea.Msg {
		item, ok := m.model.selectedItem()
		if !ok || item.Path == "" {
			return PreviewMsg{Result: app.ArtifactPreviewResult{Error: "no previewable artifact selected"}, Route: m.model.currentRoute(), Title: "Preview"}
		}
		result, err := m.model.UseCases.PreviewArtifact(m.ctx, item.Path)
		return PreviewMsg{Result: result, Err: err, Route: m.model.currentRoute(), Title: item.Label}
	}
}

package web

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxActiveOperations        = 8
	MaxPreparations            = 128
	PreparationTTL             = 2 * time.Minute
	MaxEventsPerOperation      = 256
	MaxEventBytesPerOperation  = 256 * 1024
	MaxEncodedEventBytes       = 16 * 1024
	MaxTerminalResultBytes     = 256 * 1024
	MaxSubscribersPerOperation = 8
	MaxConcurrentStreams       = 32
	SubscriberQueueSize        = 32
	TerminalRetention          = 10 * time.Minute
	SSEHeartbeat               = 15 * time.Second
	MaxStreamLifetime          = 30 * time.Minute
)

var (
	errOperationCapacity  = errors.New("operation capacity reached")
	errSubscriberCapacity = errors.New("subscriber capacity reached")
	errServerDraining     = errors.New("server draining")
	errOperationNotFound  = errors.New("operation not found")
)

type operationDocument struct {
	ID            string              `json:"id"`
	Kind          app.OperationKind   `json:"kind"`
	State         string              `json:"state"`
	Reason        string              `json:"reason,omitempty"`
	CreatedAt     time.Time           `json:"created_at"`
	StartedAt     *time.Time          `json:"started_at,omitempty"`
	FinishedAt    *time.Time          `json:"finished_at,omitempty"`
	LastEventID   string              `json:"last_event_id"`
	DurableStatus durableStatusDTO    `json:"durable_status"`
	Result        *operationResultDTO `json:"result,omitempty"`
}

type activeOperationDTO struct {
	ID        string            `json:"id"`
	Kind      app.OperationKind `json:"kind"`
	State     string            `json:"state"`
	Project   string            `json:"project,omitempty"`
	Sprint    string            `json:"sprint,omitempty"`
	Study     string            `json:"study,omitempty"`
	StartedAt *time.Time        `json:"started_at,omitempty"`
}

type durableStatusDTO struct {
	Available   bool   `json:"available"`
	RefreshPath string `json:"refresh_path,omitempty"`
}

type operationResultDTO struct {
	State     string       `json:"state"`
	Subject   string       `json:"subject,omitempty"`
	Message   string       `json:"message,omitempty"`
	Content   string       `json:"content,omitempty"`
	Truncated bool         `json:"truncated,omitempty"`
	Findings  []findingDTO `json:"findings,omitempty"`
	Error     *errorBody   `json:"error,omitempty"`
}

type operationEvent struct {
	ID   uint64
	Name string
	Data []byte
}

type operationSubscriber struct {
	id uint64
	ch chan operationEvent
}

type operationRecord struct {
	doc         operationDocument
	session     string
	request     app.OperationRequest
	cancel      context.CancelFunc
	cancelOnce  sync.Once
	done        chan struct{}
	nextEventID uint64
	events      []operationEvent
	eventBytes  int
	subscribers map[uint64]*operationSubscriber
	nextSubID   uint64
	dedupKey    string
}

type operationHub struct {
	rootCtx context.Context
	ops     app.WebOperations
	now     func() time.Time
	id      func() string

	mu       sync.Mutex
	records  map[string]*operationRecord
	dedup    map[string]string
	active   int
	streams  int
	draining bool
	counters operationCounters
}

type operationCounters struct {
	starts             atomic.Int64
	active             atomic.Int64
	terminal           atomic.Int64
	capacityRejections atomic.Int64
	cancellations      atomic.Int64
	activeStreams      atomic.Int64
	slowSubscribers    atomic.Int64
	replayGaps         atomic.Int64
	projectionDrops    atomic.Int64
	shutdownCleanups   atomic.Int64
}

func newOperationHub(rootCtx context.Context, ops app.WebOperations, now func() time.Time, id func() string) *operationHub {
	if rootCtx == nil {
		rootCtx = context.Background()
	}
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &operationHub{rootCtx: rootCtx, ops: ops, now: now, id: id, records: make(map[string]*operationRecord), dedup: make(map[string]string)}
}

func (h *operationHub) start(session string, prepared app.Confirmation) (operationDocument, error) {
	return h.startConfirmed(session, "", func() (app.Confirmation, error) { return prepared, nil })
}

func (h *operationHub) startConfirmed(session, dedupKey string, confirm func() (app.Confirmation, error)) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	if id := h.dedup[dedupKey]; dedupKey != "" && id != "" {
		if record := h.records[id]; record != nil && record.session == session {
			return cloneOperationDocument(record.doc), nil
		}
		delete(h.dedup, dedupKey)
	}
	if h.draining {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errServerDraining
	}
	if h.active >= MaxActiveOperations {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errOperationCapacity
	}
	if h.ops == nil {
		return operationDocument{}, errors.New("operation capability unavailable")
	}
	prepared, err := confirm()
	if err != nil {
		return operationDocument{}, err
	}
	id := "op_" + h.id()
	for h.records[id] != nil {
		id = "op_" + h.id()
	}
	created := h.now().UTC()
	ctx, cancel := context.WithCancel(h.rootCtx)
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		accepted, acceptErr := manager.AcceptOperation(ctx, prepared, dedupKey)
		if acceptErr != nil {
			if !errors.Is(acceptErr, app.ErrWebUnavailable) {
				cancel()
				return operationDocument{}, acceptErr
			}
		} else {
			id = accepted.RunID
			if accepted.Context != nil {
				ctx = accepted.Context
			}
			if accepted.Existing {
				doc := operationDocument{ID: id, Kind: prepared.Request.Kind, State: accepted.Lifecycle, CreatedAt: created, DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + id}}
				cancel()
				return doc, nil
			}
		}
	}
	record := &operationRecord{
		doc: operationDocument{
			ID: id, Kind: prepared.Request.Kind, State: "accepted", CreatedAt: created,
			DurableStatus: durableStatusDTO{Available: prepared.DurableRefreshPath != "", RefreshPath: prepared.DurableRefreshPath},
		},
		session: session, request: prepared.Request, cancel: cancel, done: make(chan struct{}),
		subscribers: make(map[uint64]*operationSubscriber), dedupKey: dedupKey,
	}
	h.records[id] = record
	if dedupKey != "" {
		h.dedup[dedupKey] = id
	}
	h.active++
	h.counters.starts.Add(1)
	h.counters.active.Add(1)
	h.appendEventLocked(record, "snapshot", map[string]any{"state": "accepted"})
	doc := cloneOperationDocument(record.doc)
	go h.run(ctx, record)
	return doc, nil
}

func (h *operationHub) run(ctx context.Context, record *operationRecord) {
	started := h.now().UTC()
	h.mu.Lock()
	if record.doc.State == "accepted" {
		record.doc.State = "running"
		record.doc.StartedAt = &started
		h.appendEventLocked(record, "progress", map[string]any{"message": "operation started", "state": "running"})
	}
	h.mu.Unlock()

	result, runErr := h.ops.RunOperation(ctx, record.request, func(event app.OperationEvent) {
		h.publishAppEvent(record, event)
	})
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		finishErr := manager.FinishOperation(finishCtx, record.doc.ID, result.State, runErr)
		cancel()
		if finishErr != nil && !errors.Is(finishErr, app.ErrWebUnavailable) {
			runErr = errors.Join(runErr, finishErr)
		}
	}
	h.finish(record, result, runErr)
}

func (h *operationHub) publishAppEvent(record *operationRecord, event app.OperationEvent) {
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		committed, err := manager.RecordOperationEvent(context.Background(), record.doc.ID, event)
		if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
			record.cancel()
			return
		}
		if err == nil && !committed {
			return
		}
	}
	name := "progress"
	if event.State == app.OperationFailed {
		name = "warning"
	}
	payload := map[string]any{
		"state": string(event.State), "stage": safeWebText(event.Stage), "task": safeWebText(event.Task),
		"message": safeWebText(event.Message), "completed": event.Completed, "total": event.Total, "attempt": event.Attempt,
		"event_kind": safeWebText(event.EventKind), "event_type": safeWebText(event.EventType), "tool": safeWebText(event.Tool), "action": safeWebText(event.Action),
		"tool_call_id": safeWebText(event.ToolCallID), "tool_status": safeWebText(event.ToolStatus),
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"reason": safeWebText(event.Reason), "detail": safeWebText(event.Detail),
		"runtime_attempts": event.RuntimeAttempts, "turns": event.Turns, "turns_known": event.TurnsKnown,
		"tokens": event.Tokens, "tokens_known": event.TokensKnown, "duration": safeWebText(event.Duration),
		"provider": safeWebText(event.Provider), "model": safeWebText(event.Model), "harness": safeWebText(event.Harness), "cost": safeWebText(event.Cost), "runtime_events": event.RuntimeEvents,
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	h.appendEventLocked(record, name, payload)
}

func (h *operationHub) finish(record *operationRecord, result app.OperationResult, runErr error) {
	finished := h.now().UTC()
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	state := "succeeded"
	switch {
	case errors.Is(runErr, context.Canceled), result.State == app.OperationCancelled:
		state = "cancelled"
	case runErr != nil, result.State == app.OperationFailed:
		state = "failed"
	case result.State == app.OperationPartial:
		state = "interrupted"
	}
	record.doc.State = state
	record.doc.FinishedAt = &finished
	record.doc.Result = projectOperationResult(result)
	h.appendEventLocked(record, "terminal", map[string]any{"state": state, "reason": record.doc.Reason, "result": record.doc.Result})
	h.active--
	h.counters.active.Add(-1)
	h.counters.terminal.Add(1)
	close(record.done)
	for id, subscriber := range record.subscribers {
		close(subscriber.ch)
		delete(record.subscribers, id)
		h.streams--
		h.counters.activeStreams.Add(-1)
	}
}

func (h *operationHub) status(session, id string) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return operationDocument{}, errOperationNotFound
	}
	return cloneOperationDocument(record.doc), nil
}

func (h *operationHub) activeOperations(session string) []activeOperationDTO {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	result := make([]activeOperationDTO, 0, h.active)
	for _, record := range h.records {
		if record.session != session || terminalOperationState(record.doc.State) {
			continue
		}
		result = append(result, activeOperationDTO{
			ID: record.doc.ID, Kind: record.doc.Kind, State: record.doc.State,
			Project: record.request.Project, Sprint: record.request.Sprint, Study: record.request.Study,
			StartedAt: record.doc.StartedAt,
		})
	}
	sort.Slice(result, func(i, j int) bool {
		left, right := result[i].StartedAt, result[j].StartedAt
		if left == nil || right == nil {
			return left != nil
		}
		return left.After(*right)
	})
	return result
}

func (h *operationHub) cancelOperation(session, id, reason string) (operationDocument, bool, error) {
	h.mu.Lock()
	record := h.records[id]
	if record == nil || (session != "" && record.session != session) {
		h.mu.Unlock()
		return operationDocument{}, false, errOperationNotFound
	}
	if terminalOperationState(record.doc.State) {
		doc := cloneOperationDocument(record.doc)
		h.mu.Unlock()
		return doc, false, nil
	}
	requested := false
	record.cancelOnce.Do(func() {
		requested = true
		record.doc.State = "cancelling"
		record.doc.Reason = canonicalCancelReason(reason)
		h.appendEventLocked(record, "cancel_requested", map[string]any{"reason": record.doc.Reason})
	})
	doc := cloneOperationDocument(record.doc)
	cancel := record.cancel
	h.mu.Unlock()
	if requested {
		h.counters.cancellations.Add(1)
		cancel()
	}
	return doc, requested, nil
}

func (h *operationHub) subscribe(session, id string, lastID uint64) ([]operationEvent, <-chan operationEvent, func(), error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return nil, nil, nil, errOperationNotFound
	}
	if h.streams >= MaxConcurrentStreams || len(record.subscribers) >= MaxSubscribersPerOperation {
		h.counters.capacityRejections.Add(1)
		return nil, nil, nil, errSubscriberCapacity
	}
	if lastID > 0 && len(record.events) > 0 && lastID < record.events[0].ID-1 {
		h.counters.replayGaps.Add(1)
		h.appendEventLocked(record, "recovery_required", map[string]any{
			"oldest_retained_id": strconv.FormatUint(record.events[0].ID, 10),
			"newest_retained_id": strconv.FormatUint(record.nextEventID, 10),
			"refresh_path":       record.doc.DurableStatus.RefreshPath,
		})
		h.appendEventLocked(record, "snapshot", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
	}
	replay := make([]operationEvent, 0, len(record.events))
	for _, event := range record.events {
		if event.ID > lastID {
			replay = append(replay, event)
		}
	}
	record.nextSubID++
	sub := &operationSubscriber{id: record.nextSubID, ch: make(chan operationEvent, SubscriberQueueSize)}
	if terminalOperationState(record.doc.State) {
		close(sub.ch)
	} else {
		record.subscribers[sub.id] = sub
		h.streams++
		h.counters.activeStreams.Add(1)
	}
	var once sync.Once
	unsubscribe := func() {
		once.Do(func() {
			h.mu.Lock()
			defer h.mu.Unlock()
			if current, ok := record.subscribers[sub.id]; ok {
				delete(record.subscribers, sub.id)
				h.streams--
				h.counters.activeStreams.Add(-1)
				close(current.ch)
			}
		})
	}
	return replay, sub.ch, unsubscribe, nil
}

func (h *operationHub) appendEventLocked(record *operationRecord, name string, payload any) {
	name = stableOperationEventName(name)
	record.nextEventID++
	body := map[string]any{
		"operation_id": record.doc.ID,
		"time":         h.now().UTC().Format(time.RFC3339Nano),
		"sequence":     record.nextEventID,
		"payload":      payload,
	}
	data, err := json.Marshal(body)
	if err != nil {
		h.counters.projectionDrops.Add(1)
		return
	}
	if len(data) > MaxEncodedEventBytes {
		data, _ = json.Marshal(map[string]any{
			"operation_id": record.doc.ID, "time": h.now().UTC().Format(time.RFC3339Nano),
			"sequence": record.nextEventID, "payload": map[string]any{"message": "event projection exceeded the safe size limit"},
		})
		name = "warning"
	}
	event := operationEvent{ID: record.nextEventID, Name: name, Data: data}
	record.events = append(record.events, event)
	record.eventBytes += len(data)
	for len(record.events) > MaxEventsPerOperation || record.eventBytes > MaxEventBytesPerOperation {
		record.eventBytes -= len(record.events[0].Data)
		record.events = record.events[1:]
	}
	record.doc.LastEventID = strconv.FormatUint(event.ID, 10)
	for id, subscriber := range record.subscribers {
		select {
		case subscriber.ch <- event:
		default:
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
			h.counters.slowSubscribers.Add(1)
		}
	}
}

func stableOperationEventName(name string) string {
	switch name {
	case "snapshot", "progress", "warning", "finding", "artifact", "cancel_requested", "recovery_required", "terminal":
		return name
	default:
		return "progress"
	}
}

func (h *operationHub) drainAndWait(ctx context.Context) error {
	h.mu.Lock()
	h.draining = true
	var records []*operationRecord
	for _, record := range h.records {
		if !terminalOperationState(record.doc.State) {
			records = append(records, record)
		}
	}
	h.mu.Unlock()
	for _, record := range records {
		_, _, _ = h.cancelOperation("", record.doc.ID, "server_shutdown")
	}
	h.counters.shutdownCleanups.Add(int64(len(records)))
	for _, record := range records {
		select {
		case <-record.done:
		case <-ctx.Done():
			persistErr := h.persistCleanupUncertain(records)
			h.markCleanupUncertain(records)
			return errors.Join(ctx.Err(), persistErr)
		}
	}
	return nil
}

func (h *operationHub) persistCleanupUncertain(records []*operationRecord) error {
	recorder, ok := h.ops.(app.OperationCleanupRecorder)
	if !ok {
		return errors.New("operation capability cannot persist cleanup uncertainty")
	}
	var result error
	for _, record := range records {
		h.mu.Lock()
		terminal := terminalOperationState(record.doc.State)
		h.mu.Unlock()
		if terminal {
			continue
		}
		persistCtx, cancel := context.WithTimeout(context.Background(), time.Second)
		err := recorder.RecordOperationCleanupUncertain(persistCtx, app.OperationCleanupUncertain{
			OperationID: record.doc.ID,
			Request:     record.request,
			Reason:      "server_shutdown",
			RecordedAt:  h.now().UTC(),
		})
		cancel()
		if err != nil {
			result = errors.Join(result, fmt.Errorf("persist cleanup uncertainty for %s: %w", record.doc.ID, err))
		}
	}
	return result
}

func (h *operationHub) markCleanupUncertain(records []*operationRecord) {
	h.mu.Lock()
	defer h.mu.Unlock()
	finished := h.now().UTC()
	for _, record := range records {
		if terminalOperationState(record.doc.State) {
			continue
		}
		record.doc.State = "cleanup_uncertain"
		record.doc.Reason = "server_shutdown"
		record.doc.FinishedAt = &finished
		record.doc.Result = &operationResultDTO{State: "cleanup_uncertain", Message: "Cleanup did not finish before the shutdown deadline. Refresh durable status before retrying."}
		h.appendEventLocked(record, "terminal", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
		h.active--
		h.counters.active.Add(-1)
		h.counters.terminal.Add(1)
		close(record.done)
		for id, subscriber := range record.subscribers {
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
		}
	}
}

func (h *operationHub) isDraining() bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.draining
}

func (h *operationHub) reapLocked() {
	now := h.now().UTC()
	for id, record := range h.records {
		if record.doc.FinishedAt != nil && now.Sub(*record.doc.FinishedAt) >= TerminalRetention {
			delete(h.records, id)
			if record.dedupKey != "" {
				delete(h.dedup, record.dedupKey)
			}
		}
	}
}

func projectOperationResult(result app.OperationResult) *operationResultDTO {
	out := &operationResultDTO{
		State: safeWebText(string(result.State)), Subject: safeWebText(result.Subject), Message: safeWebText(result.Message),
		Content: safeProjectedText(result.Content, MaxTerminalResultBytes/2), Truncated: result.Truncated,
	}
	for _, finding := range result.Findings {
		out.Findings = append(out.Findings, findingDTO{
			Severity: safeWebText(finding.Severity), Section: safeWebText(finding.Section), Problem: safeWebText(finding.Problem),
			Cause: safeWebText(finding.Cause), Suggestion: safeWebText(finding.Suggestion),
		})
	}
	if result.Error != nil {
		out.Error = &errorBody{Code: safeWebText(result.Error.Code), Message: safeWebText(result.Error.Message), Retryable: result.Error.Retryable, Details: map[string]any{
			"category": safeWebText(result.Error.Category), "component": safeWebText(result.Error.Component), "cause": safeWebText(result.Error.Cause), "guidance": safeWebText(result.Error.Guidance),
		}}
	}
	if data, _ := json.Marshal(out); len(data) > MaxTerminalResultBytes {
		out.Content = ""
		out.Findings = nil
		out.Truncated = true
		out.Message = safeBoundedText(out.Message, 4096)
	}
	return out
}

func cloneOperationDocument(doc operationDocument) operationDocument {
	clone := doc
	if doc.Result != nil {
		result := *doc.Result
		result.Findings = append([]findingDTO(nil), doc.Result.Findings...)
		if doc.Result.Error != nil {
			err := *doc.Result.Error
			result.Error = &err
		}
		clone.Result = &result
	}
	return clone
}

func terminalOperationState(state string) bool {
	switch state {
	case "succeeded", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		return true
	default:
		return false
	}
}

func canonicalCancelReason(reason string) string {
	switch reason {
	case "server_shutdown", "timeout", "recovery":
		return reason
	default:
		return "user_request"
	}
}

func safeWebText(value string) string {
	return safeProjectedText(value, 4096)
}

func safeProjectedText(value string, limit int) string {
	value = strings.TrimSpace(value)
	lower := strings.ToLower(value)
	for _, marker := range []string{"token=", "secret=", "authorization:", "cookie:"} {
		if index := strings.Index(lower, marker); index >= 0 {
			value = value[:index] + "[redacted]"
			lower = strings.ToLower(value)
		}
	}
	if strings.Contains(value, "/home/") || strings.Contains(value, `C:\\Users\\`) {
		value = "[redacted path]"
	}
	return safeBoundedText(value, limit)
}

func safeBoundedText(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	return value[:limit] + "…"
}

func parseEventID(value string) (uint64, error) {
	if strings.TrimSpace(value) == "" {
		return 0, nil
	}
	id, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid Last-Event-ID")
	}
	return id, nil
}

package tui

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

type Tab string

const (
	TabProjects Tab = "projects"
	TabStudies  Tab = "studies"
	TabRuns     Tab = "runs"
)

type FocusArea string

const (
	FocusTabs    FocusArea = "tabs"
	FocusContent FocusArea = "content"
)

type RouteKind string

const (
	RouteProjects       RouteKind = "projects"
	RouteProject        RouteKind = "project"
	RouteProjectSprints RouteKind = "project-sprints"
	RouteProjectDocs    RouteKind = "project-docs"
	RouteSprint         RouteKind = "sprint"
	RouteSprintQA       RouteKind = "sprint-qa"
	RouteSprintQAShard  RouteKind = "sprint-qa-shard"
	RouteSprintQATheory RouteKind = "sprint-qa-theory"
	RouteStudies        RouteKind = "studies"
	RouteStudy          RouteKind = "study"
	RouteStudyDims      RouteKind = "study-dimensions"
	RouteStudySources   RouteKind = "study-sources"
	RouteRuns           RouteKind = "runs"
	RouteRun            RouteKind = "run"
)

type Route struct {
	Kind    RouteKind
	Project string
	Sprint  string
	Study   string
	RunID   string
	Shard   string
	Theory  string
}

type Model struct {
	UseCases              app.OperationalUseCases
	Data                  app.DashboardResult
	ActiveTab             Tab
	Focus                 FocusArea
	Routes                []Route
	Selected              int
	Preview               *app.ArtifactPreviewResult
	PreviewTitle          string
	Error                 string
	Loading               bool
	Quit                  bool
	PreviewOffset         int
	Validation            *app.ValidationOperationResult
	Confirmation          *app.Confirmation
	Operation             *app.OperationResult
	Events                []app.OperationEvent
	Running               bool
	RunViewStudy          string
	RunViewShowPrevious   bool
	ActiveOperation       app.OperationRequest
	OperationShowPrevious bool
	OperationHidden       bool
	ParallelForm          *app.OperationRequest
	ParallelValue         string
	ParallelError         string
	ActiveRunID           string
	Runs                  []app.RunSnapshot
	DurableEvents         []app.RunEvent
}

type Message interface{}

type LoadMsg struct {
	Result app.DashboardResult
	Runs   []app.RunSnapshot
	Events []app.RunEvent
	Err    error
}
type RefreshMsg struct {
	Result app.DashboardResult
	Runs   []app.RunSnapshot
	Events []app.RunEvent
	Err    error
}
type PreviewMsg struct {
	Result app.ArtifactPreviewResult
	Err    error
	Route  Route
	Title  string
}
type KeyMsg string
type ValidationMsg struct {
	Result app.ValidationOperationResult
	Err    error
	Route  Route
}
type ConfirmationMsg struct {
	Result app.Confirmation
	Err    error
	Route  Route
}
type OperationMsg struct {
	Result app.OperationResult
	Err    error
	Route  Route
	Events []app.OperationEvent
}
type OperationEventMsg struct{ Event app.OperationEvent }

type navItem struct {
	Label      string
	Route      *Route
	Path       string
	Validation *app.ValidationRequest
	Operation  *app.OperationRequest
	ViewRun    string
}

func NewModel(useCases app.OperationalUseCases) Model {
	return Model{
		UseCases:  useCases,
		ActiveTab: TabProjects,
		Focus:     FocusContent,
		Routes:    []Route{{Kind: RouteProjects}},
		Loading:   true,
	}
}

func (m Model) Load(ctx context.Context) (Model, error) {
	result, err := m.UseCases.Dashboard(ctx)
	return m.Update(LoadMsg{Result: result, Err: err}), err
}

func (m Model) Refresh(ctx context.Context) (Model, error) {
	result, err := m.UseCases.Dashboard(ctx)
	return m.Update(RefreshMsg{Result: result, Err: err}), err
}

func (m Model) PreviewSelected(ctx context.Context) (Model, error) {
	item, ok := m.selectedItem()
	if !ok || item.Path == "" {
		return m.Update(PreviewMsg{Result: app.ArtifactPreviewResult{Error: "no previewable artifact selected"}, Route: m.currentRoute(), Title: "Preview"}), nil
	}
	result, err := m.UseCases.PreviewArtifact(ctx, item.Path)
	return m.Update(PreviewMsg{Result: result, Err: err, Route: m.currentRoute(), Title: item.Label}), err
}

func (m Model) Update(msg Message) Model {
	switch v := msg.(type) {
	case LoadMsg:
		m.Loading = false
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Data = v.Result
		m.Runs = v.Runs
		m.DurableEvents = dedupeDurableEvents(v.Events)
		m.Error = ""
		m.clampSelection()
	case RefreshMsg:
		m.Loading = false
		m.Preview = nil
		m.PreviewOffset = 0
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Data = v.Result
		m.Runs = v.Runs
		m.DurableEvents = dedupeDurableEvents(v.Events)
		m.Error = ""
		m.clampSelection()
	case PreviewMsg:
		if v.Route != (Route{}) && v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Preview = &v.Result
		m.PreviewTitle = v.Title
		m.Error = ""
		m.PreviewOffset = 0
	case ValidationMsg:
		m.Loading = false
		if v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Validation = &v.Result
		m.Error = ""
	case ConfirmationMsg:
		m.Loading = false
		if v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Confirmation = &v.Result
	case OperationEventMsg:
		if !m.Running {
			return m
		}
		m.Events = append(m.Events, v.Event)
		if len(m.Events) > 100 {
			m.Events = m.Events[len(m.Events)-100:]
		}
	case OperationMsg:
		m.Running = false
		m.Loading = false
		m.Confirmation = nil
		m.Operation = &v.Result
		m.Events = append(m.Events, v.Events...)
		if len(m.Events) > 100 {
			m.Events = m.Events[len(m.Events)-100:]
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
		}
	case KeyMsg:
		switch KeyToAction(string(v)) {
		case ActionQuit:
			m.Quit = true
		case ActionFocusNext:
			if m.ActiveTab == TabProjects {
				m.setTab(TabStudies)
			} else {
				m.setTab(TabProjects)
			}
		case ActionBack:
			if m.Running && !m.OperationHidden {
				return m
			} else if m.ParallelForm != nil {
				m.ParallelForm = nil
				m.ParallelValue = ""
				m.ParallelError = ""
			} else if m.RunViewStudy != "" {
				m.RunViewStudy = ""
				m.RunViewShowPrevious = false
				m.Operation = nil
				m.Events = nil
			} else if m.Confirmation != nil {
				m.Confirmation = nil
			} else if m.Operation != nil && !m.OperationHidden {
				m.Operation = nil
				m.Events = nil
				m.ActiveOperation = app.OperationRequest{}
				m.OperationShowPrevious = false
			} else if m.Validation != nil {
				m.Validation = nil
			} else if m.Preview != nil {
				m.Preview = nil
				m.PreviewOffset = 0
			} else if m.Focus == FocusContent && len(m.Routes) > 1 {
				m.Routes = m.Routes[:len(m.Routes)-1]
				m.Selected = 0
			}
		case ActionUp:
			if m.Preview != nil {
				m.PreviewOffset--
				if m.PreviewOffset < 0 {
					m.PreviewOffset = 0
				}
			} else if m.Focus == FocusContent && m.Selected > 0 {
				m.Selected--
			} else if m.Focus == FocusContent && m.Selected == 0 {
				m.Focus = FocusTabs
			}
		case ActionDown:
			if m.Preview != nil {
				m.PreviewOffset++
			} else if m.Focus == FocusTabs {
				m.Focus = FocusContent
			} else if m.Focus == FocusContent {
				m.Selected++
				m.clampSelection()
			}
		case ActionLeft:
			if m.Focus == FocusTabs {
				if m.ActiveTab == TabRuns {
					m.setTab(TabStudies)
				} else {
					m.setTab(TabProjects)
				}
				m.Focus = FocusTabs
			}
		case ActionRight:
			if m.Focus == FocusTabs {
				if m.ActiveTab == TabProjects {
					m.setTab(TabStudies)
					m.Focus = FocusTabs
				} else {
					m.Focus = FocusContent
				}
			}
		case ActionProjects:
			m.setTab(TabProjects)
		case ActionStudies:
			m.setTab(TabStudies)
		case ActionRuns:
			m.setTab(TabRuns)
		case ActionOpen:
			if m.Preview != nil {
				return m
			}
			if m.Focus == FocusTabs {
				m.Focus = FocusContent
				return m
			}
			if item, ok := m.selectedItem(); ok && item.Route != nil {
				m.Routes = append(m.Routes, *item.Route)
				m.Selected = 0
			}
		}
	}
	return m
}

func dedupeDurableEvents(events []app.RunEvent) []app.RunEvent {
	seen := make(map[string]bool, len(events))
	result := make([]app.RunEvent, 0, min(len(events), 200))
	for _, event := range events {
		key := string(event.RunID) + ":" + fmt.Sprint(event.Sequence)
		if seen[key] {
			continue
		}
		seen[key] = true
		result = append(result, event)
	}
	if len(result) > 200 {
		result = result[len(result)-200:]
	}
	return result
}

func (m *Model) setTab(tab Tab) {
	m.ActiveTab = tab
	m.Focus = FocusContent
	m.Selected = 0
	m.Preview = nil
	m.PreviewOffset = 0
	if tab == TabStudies {
		m.Routes = []Route{{Kind: RouteStudies}}
		return
	}
	if tab == TabRuns {
		m.Routes = []Route{{Kind: RouteRuns}}
		return
	}
	m.Routes = []Route{{Kind: RouteProjects}}
}

func (m *Model) clampSelection() {
	max := len(m.navItems()) - 1
	if max < 0 {
		m.Selected = 0
		return
	}
	if m.Selected > max {
		m.Selected = max
	}
}

func (m Model) currentRoute() Route {
	if len(m.Routes) == 0 {
		if m.ActiveTab == TabStudies {
			return Route{Kind: RouteStudies}
		}
		if m.ActiveTab == TabRuns {
			return Route{Kind: RouteRuns}
		}
		return Route{Kind: RouteProjects}
	}
	return m.Routes[len(m.Routes)-1]
}

func (m Model) selectedItem() (navItem, bool) {
	items := m.navItems()
	if m.Selected < 0 || m.Selected >= len(items) {
		return navItem{}, false
	}
	return items[m.Selected], true
}

func (m Model) navItems() []navItem {
	route := m.currentRoute()
	switch route.Kind {
	case RouteProjects:
		items := make([]navItem, 0, len(m.Data.Projects))
		for _, p := range m.Data.Projects {
			items = append(items, navItem{Label: p.Name, Route: &Route{Kind: RouteProject, Project: p.Name}})
		}
		return items
	case RouteProject:
		return []navItem{
			{Label: "Sprints", Route: &Route{Kind: RouteProjectSprints, Project: route.Project}},
			{Label: "Docs", Route: &Route{Kind: RouteProjectDocs, Project: route.Project}},
			{Label: "Project Index", Path: projectArtifactPath(m.Data.Projects, route.Project, "project-index")},
			{Label: "Roadmap", Path: projectArtifactPath(m.Data.Projects, route.Project, "roadmap")},
			{Label: "Validate Project", Validation: &app.ValidationRequest{Subject: app.ValidationProject, Project: route.Project}},
		}
	case RouteProjectSprints:
		var items []navItem
		for _, s := range m.Data.Sprints {
			if s.Project == route.Project {
				sprintRoute := Route{Kind: RouteSprint, Project: s.Project, Sprint: s.Slug}
				items = append(items, navItem{Label: s.Slug, Route: &sprintRoute})
			}
		}
		return items
	case RouteProjectDocs:
		if p, ok := findProject(m.Data.Projects, route.Project); ok {
			var items []navItem
			for _, artifact := range p.Artifacts {
				if artifact.Label == "doc" {
					items = append(items, navItem{Label: filepath.Base(artifact.Path), Path: artifact.Path})
				}
			}
			return items
		}
	case RouteSprint:
		if s, ok := findSprint(m.Data.Sprints, route.Project, route.Sprint); ok {
			stageLabel := func(stage string) string {
				if stage == "review" {
					return "Conformance Review"
				}
				return stage
			}
			items := []navItem{
				{Label: "Requirements", Path: artifactByLabel(s.Artifacts, "requirements")},
				{Label: "Sprint Index", Path: artifactByLabel(s.Artifacts, "sprint-index")},
				{Label: "Technical Handbook", Path: artifactByLabel(s.Artifacts, "technical-handbook")},
				{Label: "Reasoning", Path: artifactByLabel(s.Artifacts, "reasoning")},
				{Label: "Plan", Path: artifactByLabel(s.Artifacts, "plan")},
				{Label: "Execute", Path: artifactByLabel(s.Artifacts, "execute")},
				{Label: "Conformance Review", Path: artifactByLabel(s.Artifacts, "review")},
				{Label: "Smoke", Path: artifactByLabel(s.Artifacts, "smoke")},
				{Label: "Flow State", Path: artifactByLabel(s.Artifacts, "flow-state")},
				{Label: "Run State", Path: artifactByLabel(s.Artifacts, "run-state")},
				{Label: "QA", Route: &Route{Kind: RouteSprintQA, Project: route.Project, Sprint: route.Sprint}},
			}
			stages := []string{"requirements", "sprint-index", "technical-handbook", "area-reasoning", "reasoning", "plan", "execute", "review"}
			items = append(items, navItem{Label: "Sprint Status", Operation: &app.OperationRequest{Kind: app.OperationSprintStatus, Project: route.Project, Sprint: route.Sprint}})
			for _, stage := range stages {
				items = append(items, navItem{Label: "Validate " + stageLabel(stage), Validation: &app.ValidationRequest{Subject: app.ValidationSprint, Project: route.Project, Sprint: route.Sprint, Stage: stage}})
				items = append(items, navItem{Label: "Preview " + stageLabel(stage) + " Prompt", Operation: &app.OperationRequest{Kind: app.OperationPrompt, Project: route.Project, Sprint: route.Sprint, Stage: stage}})
			}
			items = append(items,
				navItem{Label: "Dry Run Flow to smoke", Operation: &app.OperationRequest{Kind: app.OperationFlowDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Run Flow to smoke [RUNTIME + EXTERNAL]", Operation: &app.OperationRequest{Kind: app.OperationFlow, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}})
			for _, stage := range stages {
				items = append(items,
					navItem{Label: "Dry Run Flow to " + stageLabel(stage), Operation: &app.OperationRequest{Kind: app.OperationFlowDryRun, Project: route.Project, Sprint: route.Sprint, Stage: stage}},
					navItem{Label: "Run Flow to " + stageLabel(stage) + " [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationFlow, Project: route.Project, Sprint: route.Sprint, Stage: stage}})
			}
			items = append(items,
				navItem{Label: "Execute Status", Operation: &app.OperationRequest{Kind: app.OperationExecuteStatus, Project: route.Project, Sprint: route.Sprint, Stage: "execute"}},
				navItem{Label: "Execute Dry Run", Operation: &app.OperationRequest{Kind: app.OperationExecuteDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "execute"}},
				navItem{Label: "Execute Start [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationExecuteStart, Project: route.Project, Sprint: route.Sprint, Stage: "execute"}},
				navItem{Label: "Execute Resume [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationExecuteResume, Project: route.Project, Sprint: route.Sprint, Stage: "execute"}})
			items = append(items,
				navItem{Label: "Conformance Review Status", Operation: &app.OperationRequest{Kind: app.OperationReviewStatus, Project: route.Project, Sprint: route.Sprint, Stage: "review"}},
				navItem{Label: "Conformance Review Dry Run", Operation: &app.OperationRequest{Kind: app.OperationReviewDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "review"}},
				navItem{Label: "Run/Resume Conformance Review [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationReviewStart, Project: route.Project, Sprint: route.Sprint, Stage: "review"}},
				navItem{Label: "Restart Conformance Review [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationReviewStart, Project: route.Project, Sprint: route.Sprint, Stage: "review", RestartReview: true}})
			items = append(items,
				navItem{Label: "Verify to Conformance Review Preview", Operation: &app.OperationRequest{Kind: app.OperationVerifyDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "review"}},
				navItem{Label: "Verify to Conformance Review [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationVerifyStart, Project: route.Project, Sprint: route.Sprint, Stage: "review"}},
				navItem{Label: "Verify to Smoke Preview", Operation: &app.OperationRequest{Kind: app.OperationVerifyDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Verify to Smoke [RUNTIME + EXTERNAL]", Operation: &app.OperationRequest{Kind: app.OperationVerifyStart, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Validate smoke", Validation: &app.ValidationRequest{Subject: app.ValidationSprint, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Smoke Status", Operation: &app.OperationRequest{Kind: app.OperationSmokeStatus, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Smoke Preview", Operation: &app.OperationRequest{Kind: app.OperationSmokeDryRun, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Run Smoke [EXTERNAL]", Operation: &app.OperationRequest{Kind: app.OperationSmokeStart, Project: route.Project, Sprint: route.Sprint, Stage: "smoke"}},
				navItem{Label: "Run Smoke Diagnostic Override [EXTERNAL]", Operation: &app.OperationRequest{Kind: app.OperationSmokeStart, Project: route.Project, Sprint: route.Sprint, Stage: "smoke", ForceReview: true, OverrideRationale: "operator requested guarded TUI diagnostic evidence"}})
			return items
		}
	case RouteSprintQA:
		if s, ok := findSprint(m.Data.Sprints, route.Project, route.Sprint); ok {
			items := []navItem{
				{Label: "QA Status", Operation: &app.OperationRequest{Kind: app.OperationQAStatus, Project: route.Project, Sprint: route.Sprint}},
				{Label: "QA Dry Run", Operation: &app.OperationRequest{Kind: app.OperationQADryRun, Project: route.Project, Sprint: route.Sprint}},
				{Label: "Start QA [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationQAStart, Project: route.Project, Sprint: route.Sprint}},
				{Label: "Resume QA [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationQAResume, Project: route.Project, Sprint: route.Sprint}},
				{Label: "Recover QA", Operation: &app.OperationRequest{Kind: app.OperationQARecover, Project: route.Project, Sprint: route.Sprint}},
			}
			if s.QA.RunID != "" {
				items = append(items, navItem{Label: "View QA durable run  " + s.QA.RunID, Route: &Route{Kind: RouteRun, RunID: s.QA.RunID}})
			}
			for _, shard := range s.QA.Shards {
				items = append(items, navItem{Label: shard.Title + "  " + shard.Phase, Route: &Route{Kind: RouteSprintQAShard, Project: route.Project, Sprint: route.Sprint, Shard: shard.ID}})
			}
			return items
		}
	case RouteSprintQAShard:
		items := []navItem{
			{Label: "Run focused shard [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationQAStart, Project: route.Project, Sprint: route.Sprint, Task: route.Shard}},
			{Label: "Resume focused shard [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationQAResume, Project: route.Project, Sprint: route.Sprint, Task: route.Shard}},
		}
		if s, ok := findSprint(m.Data.Sprints, route.Project, route.Sprint); ok {
			for _, shard := range s.QA.Shards {
				if shard.ID != route.Shard {
					continue
				}
				for _, theory := range shard.Theories {
					items = append(items, navItem{Label: theory.Claim + "  " + theory.Outcome, Route: &Route{Kind: RouteSprintQATheory, Project: route.Project, Sprint: route.Sprint, Shard: shard.ID, Theory: theory.ID}})
				}
			}
		}
		return items
	case RouteStudies:
		items := make([]navItem, 0, len(m.Data.Studies))
		for _, s := range m.Data.Studies {
			items = append(items, navItem{Label: s.Name, Route: &Route{Kind: RouteStudy, Study: s.Name}})
		}
		return items
	case RouteStudy:
		var items []navItem
		if summary, ok := findStudy(m.Data.Studies, route.Study); ok && summary.RunActive {
			items = append(items, navItem{Label: "View Run [ACTIVE]", ViewRun: route.Study})
		} else {
			items = append(items, navItem{Label: "Run Loop [RUNTIME]", Operation: &app.OperationRequest{Kind: app.OperationStudyResume, Study: route.Study, Parallelism: 3}})
		}
		items = append(items,
			navItem{Label: "Dimensions", Route: &Route{Kind: RouteStudyDims, Study: route.Study}},
			navItem{Label: "Sources", Route: &Route{Kind: RouteStudySources, Study: route.Study}},
			navItem{Label: "Run State", Path: studyArtifactPath(m.Data.Studies, route.Study, "run-state")},
			navItem{Label: "Validate Study", Validation: &app.ValidationRequest{Subject: app.ValidationStudy, Study: route.Study}},
		)
		return items
	case RouteStudyDims:
		if s, ok := findStudy(m.Data.Studies, route.Study); ok {
			return artifactItemsByLabel(s.Artifacts, "dimension")
		}
	case RouteStudySources:
		if s, ok := findStudy(m.Data.Studies, route.Study); ok {
			return artifactItemsByLabel(s.Artifacts, "source")
		}
	case RouteRuns:
		items := make([]navItem, 0, len(m.Runs))
		for _, run := range m.Runs {
			label := string(run.RunID) + "  " + string(run.Lifecycle) + "  " + run.Target.Kind + "/" + run.Target.Operation
			items = append(items, navItem{Label: label, Route: &Route{Kind: RouteRun, RunID: string(run.RunID)}})
		}
		return items
	}
	return nil
}

func (m Model) breadcrumb() string {
	route := m.currentRoute()
	switch route.Kind {
	case RouteProject:
		return "Projects > " + route.Project
	case RouteProjectSprints:
		return "Projects > " + route.Project + " > Sprints"
	case RouteProjectDocs:
		return "Projects > " + route.Project + " > Docs"
	case RouteSprint:
		return "Projects > " + route.Project + " > Sprints > " + route.Sprint
	case RouteSprintQA:
		return "Projects > " + route.Project + " > Sprints > " + route.Sprint + " > QA"
	case RouteSprintQAShard:
		return "Projects > " + route.Project + " > Sprints > " + route.Sprint + " > QA > " + route.Shard
	case RouteSprintQATheory:
		return "Projects > " + route.Project + " > Sprints > " + route.Sprint + " > QA > " + route.Theory
	case RouteStudy:
		return "Studies > " + route.Study
	case RouteStudyDims:
		return "Studies > " + route.Study + " > Dimensions"
	case RouteStudySources:
		return "Studies > " + route.Study + " > Sources"
	case RouteStudies:
		return "Studies"
	case RouteRuns:
		return "Runs"
	case RouteRun:
		return "Runs > " + route.RunID
	default:
		return "Projects"
	}
}

func projectArtifactPath(projects []app.ProjectSummary, project, label string) string {
	if p, ok := findProject(projects, project); ok {
		return artifactByLabel(p.Artifacts, label)
	}
	return ""
}

func studyArtifactPath(studies []app.StudySummary, study, label string) string {
	if s, ok := findStudy(studies, study); ok {
		return artifactByLabel(s.Artifacts, label)
	}
	return ""
}

func artifactItemsByLabel(artifacts []app.DisplayArtifact, label string) []navItem {
	var items []navItem
	for _, artifact := range artifacts {
		if artifact.Label == label {
			items = append(items, navItem{Label: strings.TrimSuffix(filepath.Base(artifact.Path), filepath.Ext(artifact.Path)), Path: artifact.Path})
		}
	}
	return items
}

func artifactByLabel(artifacts []app.DisplayArtifact, label string) string {
	for _, artifact := range artifacts {
		if artifact.Label == label {
			return artifact.Path
		}
	}
	return ""
}

func findProject(projects []app.ProjectSummary, name string) (app.ProjectSummary, bool) {
	for _, p := range projects {
		if p.Name == name {
			return p, true
		}
	}
	return app.ProjectSummary{}, false
}

func findSprint(sprints []app.SprintSummary, project, slug string) (app.SprintSummary, bool) {
	for _, s := range sprints {
		if s.Project == project && s.Slug == slug {
			return s, true
		}
	}
	return app.SprintSummary{}, false
}

func findStudy(studies []app.StudySummary, name string) (app.StudySummary, bool) {
	for _, s := range studies {
		if s.Name == name {
			return s, true
		}
	}
	return app.StudySummary{}, false
}

