package app

import (
	"context"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

type RunID = runcontrol.RunID
type RunQuery = runcontrol.Query
type RunPage = runcontrol.Page
type RunSnapshot = runcontrol.Snapshot
type RunEvent = runcontrol.Event
type RunLifecycle = runcontrol.Lifecycle
type RunTarget = runcontrol.Target
type RunCancellation = runcontrol.Cancellation
type RunHealthResult = runcontrol.Health
type RunOmission = runcontrol.Omission

var (
	ErrRunInvalidArgument   = runcontrol.ErrInvalidArgument
	ErrRunNotFound          = runcontrol.ErrNotFound
	ErrRunConflict          = runcontrol.ErrConflict
	ErrRunUnsupportedSchema = runcontrol.ErrUnsupportedSchema
)

// RunUseCases is the surface-neutral durable observation and command boundary.
// Its DTOs contain only sanitized facts owned by run control.
type RunUseCases interface {
	Runs(context.Context, runcontrol.Query) (runcontrol.Page, error)
	Run(context.Context, runcontrol.RunID) (runcontrol.Snapshot, error)
	RunEvents(context.Context, runcontrol.RunID, uint64, int) ([]runcontrol.Event, error)
	CancelRun(context.Context, runcontrol.RunID, string) (runcontrol.Snapshot, bool, error)
	RunHealth(context.Context) (runcontrol.Health, error)
}

type repositoryRunUseCases struct{ repository runcontrol.Repository }

func (u repositoryRunUseCases) Runs(ctx context.Context, query runcontrol.Query) (runcontrol.Page, error) {
	return u.repository.List(ctx, query)
}

func (u repositoryRunUseCases) Run(ctx context.Context, id runcontrol.RunID) (runcontrol.Snapshot, error) {
	return u.repository.Snapshot(ctx, id)
}

func (u repositoryRunUseCases) RunEvents(ctx context.Context, id runcontrol.RunID, after uint64, limit int) ([]runcontrol.Event, error) {
	return u.repository.Events(ctx, id, after, limit)
}

func (u repositoryRunUseCases) CancelRun(ctx context.Context, id runcontrol.RunID, reason string) (runcontrol.Snapshot, bool, error) {
	return u.repository.RequestCancellation(ctx, id, reason)
}

func (u repositoryRunUseCases) RunHealth(ctx context.Context) (runcontrol.Health, error) {
	return u.repository.Health(ctx)
}

package runcontrol

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

const (
	DatabaseRelativePath = ".ultraplan/run-control.db"
	BusyTimeout          = 5 * time.Second
	defaultMaxOpenConns  = 4
	maxOpenConns         = 16
	defaultEventPage     = 200
	maxEventPage         = 512
)

// SQLiteOptions controls process-local seams and connection bounds. Durable
// safety pragmas are fixed product invariants and cannot be weakened here.
type SQLiteOptions struct {
	Clock        Clock
	IDs          IDSource
	Logger       Logger
	Notifier     Notifier
	MaxOpenConns int
	Retention    RetentionPolicy
}

// SQLiteRepository is a direct multi-process repository over one workspace
// database. Every mutation uses a short immediate transaction.
type SQLiteRepository struct {
	db            *sql.DB
	path          string
	clock         Clock
	clockInjected bool
	ids           IDSource
	loggerMu      sync.RWMutex
	logger        Logger
	notifier      Notifier
	retention     RetentionPolicy
	softQuota     int64
	metrics       repositoryMetrics
}

var _ Repository = (*SQLiteRepository)(nil)

// OpenSQLite opens or creates the private workspace run-control database.
func OpenSQLite(ctx context.Context, workspaceRoot string, opts SQLiteOptions) (*SQLiteRepository, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	root, err := validateWorkspaceRoot(workspaceRoot)
	if err != nil {
		return nil, err
	}
	databasePath, err := preparePrivateDatabase(root)
	if err != nil {
		return nil, err
	}

	values := url.Values{}
	values.Set("_busy_timeout", strconv.FormatInt(BusyTimeout.Milliseconds(), 10))
	values.Set("_foreign_keys", "on")
	values.Set("_journal_mode", "WAL")
	values.Set("_synchronous", "FULL")
	values.Set("_txlock", "immediate")
	values.Set("_defensive", "1")
	dsn := (&url.URL{Scheme: "file", Path: filepath.ToSlash(databasePath), RawQuery: values.Encode()}).String()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, classifyStoreError("open", "open run-control database failed", err)
	}
	closeOnError := true
	defer func() {
		if closeOnError {
			_ = db.Close()
		}
	}()

	connections := opts.MaxOpenConns
	if connections == 0 {
		connections = defaultMaxOpenConns
	}
	if connections < 1 || connections > maxOpenConns {
		return nil, invalidField("max_open_connections", fmt.Sprintf("must be between 1 and %d", maxOpenConns))
	}
	db.SetMaxOpenConns(connections)
	db.SetMaxIdleConns(connections)
	if err := db.PingContext(ctx); err != nil {
		return nil, classifyStoreError("ping", "run-control database is unavailable", err)
	}
	if err := verifyPragmas(ctx, db); err != nil {
		return nil, err
	}
	clock := opts.Clock
	clockInjected := clock != nil
	if clock == nil {
		clock = WallClock{}
	}
	if err := migrateSchema(ctx, db, databasePath, clock); err != nil {
		return nil, err
	}
	if err := enforcePrivateMode(databasePath, 0o600); err != nil {
		return nil, err
	}

	ids := opts.IDs
	if ids == nil {
		ids = RandomIDSource{}
	}
	retention, err := normalizeRetentionPolicy(opts.Retention)
	if err != nil {
		return nil, err
	}
	repository := &SQLiteRepository{
		db: db, path: databasePath, clock: clock, clockInjected: clockInjected, ids: ids,
		logger: opts.Logger, notifier: opts.Notifier,
		retention: retention, softQuota: retention.HardQuotaBytes - ReservedHeadroomBytes,
	}
	closeOnError = false
	return repository, nil
}

func validateWorkspaceRoot(workspaceRoot string) (string, error) {
	if strings.TrimSpace(workspaceRoot) == "" {
		return "", invalidField("workspace_root", "is required")
	}
	root, err := filepath.Abs(workspaceRoot)
	if err != nil {
		return "", wrapError(CodeInvalidArgument, "resolve_workspace", "workspace root is invalid", false, err)
	}
	info, err := os.Stat(root)
	if err != nil {
		return "", classifyStoreError("stat_workspace", "workspace root cannot be inspected", err)
	}
	if !info.IsDir() {
		return "", invalidField("workspace_root", "must be a directory")
	}
	return filepath.Clean(root), nil
}

func preparePrivateDatabase(root string) (string, error) {
	directory := filepath.Join(root, ".ultraplan")
	info, err := os.Lstat(directory)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		if err := os.Mkdir(directory, 0o700); err != nil {
			return "", classifyStoreError("create_directory", "create private run-control directory failed", err)
		}
	case err != nil:
		return "", classifyStoreError("inspect_directory", "inspect run-control directory failed", err)
	case info.Mode()&os.ModeSymlink != 0 || !info.IsDir():
		return "", invalidField("run_control_directory", "must be a real directory, not a symlink")
	}
	if err := enforcePrivateMode(directory, 0o700); err != nil {
		return "", err
	}

	path := filepath.Join(directory, "run-control.db")
	info, err = os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		file, createErr := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_RDWR, 0o600)
		if createErr != nil {
			return "", classifyStoreError("create_database", "create private run-control database failed", createErr)
		}
		if closeErr := file.Close(); closeErr != nil {
			return "", classifyStoreError("close_database", "close new run-control database failed", closeErr)
		}
	case err != nil:
		return "", classifyStoreError("inspect_database", "inspect run-control database failed", err)
	case info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular():
		return "", invalidField("run_control_database", "must be a regular file, not a symlink")
	}
	if err := enforcePrivateMode(path, 0o600); err != nil {
		return "", err
	}
	return path, nil
}

func enforcePrivateMode(path string, want fs.FileMode) error {
	if err := os.Chmod(path, want); err != nil {
		return classifyStoreError("set_permissions", "set private run-control permissions failed", err)
	}
	info, err := os.Stat(path)
	if err != nil {
		return classifyStoreError("verify_permissions", "verify run-control permissions failed", err)
	}
	if got := info.Mode().Perm(); got != want {
		return wrapError(CodePermission, "verify_permissions", fmt.Sprintf("private permissions are %04o; require %04o", got, want), false, nil)
	}
	return nil
}

func verifyPragmas(ctx context.Context, db *sql.DB) error {
	checks := []struct {
		name string
		want string
	}{
		{name: "journal_mode", want: "wal"},
		{name: "synchronous", want: "2"},
		{name: "foreign_keys", want: "1"},
		{name: "busy_timeout", want: "5000"},
	}
	for _, check := range checks {
		var got string
		if err := db.QueryRowContext(ctx, "PRAGMA "+check.name).Scan(&got); err != nil {
			return classifyStoreError("verify_pragma", "verify required SQLite durability policy failed", err)
		}
		if !strings.EqualFold(got, check.want) {
			return wrapError(CodeInvariant, "verify_pragma", fmt.Sprintf("SQLite %s=%s; require %s", check.name, got, check.want), false, nil)
		}
	}
	return nil
}

const initialSchema = `
CREATE TABLE IF NOT EXISTS app_schema (
    component TEXT PRIMARY KEY,
    version INTEGER NOT NULL CHECK (version > 0),
    migrated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS runs (
    run_id TEXT PRIMARY KEY,
    target_kind TEXT NOT NULL,
    operation_kind TEXT NOT NULL,
    project_id TEXT NOT NULL DEFAULT '',
    sprint_id TEXT NOT NULL DEFAULT '',
    study_id TEXT NOT NULL DEFAULT '',
    stage_id TEXT NOT NULL DEFAULT '',
    task_id TEXT NOT NULL DEFAULT '',
    lifecycle TEXT NOT NULL CHECK (lifecycle IN ('accepted','queued','running','cancelling','succeeded','failed','cancelled','timed_out','interrupted','cleanup_uncertain','persistence_degraded')),
    liveness TEXT NOT NULL CHECK (liveness IN ('unknown','live','stalled','owner_unreachable','interrupted','cleanup_uncertain','terminal')),
    record_state TEXT NOT NULL CHECK (record_state IN ('full','compacted','tombstone')),
    accepted_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    started_at TEXT,
    finished_at TEXT,
    current_attempt_id TEXT,
    last_sequence INTEGER NOT NULL DEFAULT 0 CHECK (last_sequence >= 0),
    oldest_retained_sequence INTEGER NOT NULL DEFAULT 1 CHECK (oldest_retained_sequence >= 1),
    history_complete INTEGER NOT NULL DEFAULT 1 CHECK (history_complete IN (0,1)),
    omission_total INTEGER NOT NULL DEFAULT 0 CHECK (omission_total >= 0),
    correlation_json TEXT NOT NULL DEFAULT '{}',
    product_status TEXT NOT NULL DEFAULT '',
    confirmation_digest TEXT NOT NULL DEFAULT '',
    cancellation_state TEXT NOT NULL DEFAULT 'none' CHECK (cancellation_state IN ('none','requested','acknowledged','uncertain')),
    cancellation_reason TEXT NOT NULL DEFAULT '',
    cancellation_requested_at TEXT,
    cancellation_acknowledged_at TEXT,
    terminal_outcome TEXT CHECK (terminal_outcome IS NULL OR terminal_outcome IN ('succeeded','failed','cancelled','timed_out','interrupted','cleanup_uncertain','persistence_degraded')),
    terminal_reason TEXT NOT NULL DEFAULT '',
    terminal_at TEXT,
    terminal_proposed_by TEXT NOT NULL DEFAULT '',
    CHECK ((terminal_outcome IS NULL AND finished_at IS NULL AND lifecycle IN ('accepted','queued','running','cancelling'))
        OR (terminal_outcome IS NOT NULL AND finished_at IS NOT NULL AND terminal_outcome = lifecycle)),
    FOREIGN KEY (current_attempt_id) REFERENCES attempts(attempt_id)
);

CREATE TABLE IF NOT EXISTS attempts (
    attempt_id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL REFERENCES runs(run_id) ON DELETE CASCADE,
    ordinal INTEGER NOT NULL CHECK (ordinal > 0),
    owner_id TEXT NOT NULL,
    fencing_generation INTEGER NOT NULL CHECK (fencing_generation > 0),
    host_digest TEXT NOT NULL DEFAULT '',
    boot_id TEXT NOT NULL DEFAULT '',
    pid INTEGER NOT NULL DEFAULT 0 CHECK (pid >= 0),
    process_birth_token TEXT NOT NULL DEFAULT '',
    claimed_at TEXT NOT NULL,
    heartbeat_at TEXT NOT NULL,
    lease_expires_at TEXT NOT NULL,
    correlation_json TEXT NOT NULL DEFAULT '{}',
    outcome TEXT CHECK (outcome IS NULL OR outcome IN ('succeeded','failed','cancelled','timed_out','interrupted','cleanup_uncertain','persistence_degraded')),
    UNIQUE (run_id, ordinal),
    UNIQUE (run_id, fencing_generation)
);

CREATE TABLE IF NOT EXISTS events (
    run_id TEXT NOT NULL REFERENCES runs(run_id) ON DELETE CASCADE,
    sequence INTEGER NOT NULL CHECK (sequence > 0),
    committed_at TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN ('accepted','claimed','lifecycle','progress','message','warning','finding','artifact','cancellation','recovery','terminal','omission')),
    attempt_id TEXT,
    stage_id TEXT NOT NULL DEFAULT '',
    task_id TEXT NOT NULL DEFAULT '',
    payload_json TEXT NOT NULL DEFAULT '{}',
    omission_json TEXT,
    PRIMARY KEY (run_id, sequence),
    FOREIGN KEY (attempt_id) REFERENCES attempts(attempt_id)
);

CREATE TABLE IF NOT EXISTS operation_aliases (
    alias_id TEXT PRIMARY KEY,
    run_id TEXT REFERENCES runs(run_id) ON DELETE CASCADE,
    alias_kind TEXT NOT NULL,
    created_at TEXT NOT NULL,
    expires_at TEXT,
    recovery_code TEXT NOT NULL DEFAULT '',
    recovery_guidance TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS reconciliation_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL REFERENCES runs(run_id) ON DELETE CASCADE,
    attempt_id TEXT,
    observed_at TEXT NOT NULL,
    action TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 128),
    decision TEXT NOT NULL CHECK (length(decision) BETWEEN 1 AND 128),
    evidence_json TEXT NOT NULL DEFAULT '{}' CHECK (length(evidence_json) <= 16384),
    FOREIGN KEY (attempt_id) REFERENCES attempts(attempt_id)
);

CREATE TRIGGER IF NOT EXISTS trg_events_immutable
BEFORE UPDATE ON events
BEGIN
    SELECT RAISE(ABORT, 'run-control events are immutable');
END;

CREATE INDEX IF NOT EXISTS idx_runs_active_updated ON runs(lifecycle, updated_at DESC, run_id DESC);
CREATE INDEX IF NOT EXISTS idx_runs_target_updated ON runs(target_kind, project_id, sprint_id, study_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_runs_retention ON runs(record_state, finished_at, updated_at);
CREATE INDEX IF NOT EXISTS idx_attempts_owner_lease ON attempts(owner_id, lease_expires_at, run_id);
CREATE INDEX IF NOT EXISTS idx_attempts_run_fence ON attempts(run_id, fencing_generation DESC);
CREATE INDEX IF NOT EXISTS idx_events_replay ON events(run_id, sequence);
CREATE INDEX IF NOT EXISTS idx_events_retention ON events(committed_at, run_id, sequence);
CREATE INDEX IF NOT EXISTS idx_operation_aliases_run ON operation_aliases(run_id, alias_id);
CREATE INDEX IF NOT EXISTS idx_reconciliation_run_time ON reconciliation_log(run_id, observed_at DESC, id DESC);
`

func createInitialSchema(ctx context.Context, db *sql.DB, migratedAt time.Time) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return ctxErr
		}
		return classifyStoreError("begin_schema", "begin run-control schema transaction failed", err)
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, initialSchema); err != nil {
		return classifyStoreError("create_schema", "create run-control schema failed", err)
	}
	if _, err := tx.ExecContext(ctx, `INSERT OR REPLACE INTO app_schema (component, version, migrated_at) VALUES ('run_control', 1, ?)`, formatTime(migratedAt)); err != nil {
		return classifyStoreError("record_schema", "record run-control schema version failed", err)
	}
	if _, err := tx.ExecContext(ctx, `PRAGMA user_version = 1`); err != nil {
		return classifyStoreError("record_user_version", "record SQLite user version failed", err)
	}
	if err := tx.Commit(); err != nil {
		return classifyStoreError("commit_schema", "commit run-control schema failed", err)
	}
	return nil
}

func (r *SQLiteRepository) Close() error {
	if r == nil || r.db == nil {
		return nil
	}
	if err := r.db.Close(); err != nil {
		return classifyStoreError("close", "close run-control database failed", err)
	}
	return nil
}

func (r *SQLiteRepository) Accept(ctx context.Context, input Acceptance) (snapshotResult Snapshot, resultErr error) {
	metricStarted := time.Now()
	defer func() { r.metrics.acceptance.observe(metricStarted, resultErr) }()
	if ctx == nil {
		ctx = context.Background()
	}
	if usage, err := r.storageBytes(); err != nil {
		return Snapshot{}, err
	} else if usage >= r.retention.HardQuotaBytes*80/100 {
		if _, compactErr := r.Compact(ctx, 64); compactErr != nil {
			return Snapshot{}, compactErr
		}
	}
	if usage, err := r.storageBytes(); err != nil {
		return Snapshot{}, err
	} else if usage >= r.softQuota {
		return Snapshot{}, wrapError(CodeQuota, "accept_quota", "run-control soft quota prevents new acceptance", true, nil)
	}
	if err := input.Target.Validate(); err != nil {
		return Snapshot{}, err
	}
	if err := input.Correlation.Validate(); err != nil {
		return Snapshot{}, err
	}
	if len(input.ProductStatus) > MaxSafeValueBytes || len(input.ConfirmationDigest) > MaxSafeValueBytes {
		return Snapshot{}, invalidField("acceptance", "contains an unbounded status or confirmation digest")
	}
	runID := input.RunID
	var err error
	if runID == "" {
		runID, err = r.ids.NewRunID()
		if err != nil {
			return Snapshot{}, err
		}
	}
	if err := runID.Validate(); err != nil {
		return Snapshot{}, err
	}
	correlation, err := marshalBounded(input.Correlation, MaxSafeValueBytes*8)
	if err != nil {
		return Snapshot{}, err
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return Snapshot{}, ctxErr
		}
		return Snapshot{}, classifyStoreError("accept_begin", "begin durable acceptance failed", err)
	}
	defer tx.Rollback()
	_, err = tx.ExecContext(ctx, `
INSERT INTO runs (
    run_id, target_kind, operation_kind, project_id, sprint_id, study_id, stage_id, task_id,
    lifecycle, liveness, record_state, accepted_at, updated_at, correlation_json,
    product_status, confirmation_digest, cancellation_state
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		string(runID), input.Target.Kind, input.Target.Operation, input.Target.Project, input.Target.Sprint,
		input.Target.Study, input.Target.Stage, input.Target.Task, string(LifecycleAccepted), string(LivenessUnknown),
		string(RecordFull), formatTime(now), formatTime(now), correlation, input.ProductStatus,
		input.ConfirmationDigest, string(CancellationNone))
	if err != nil {
		if isConstraint(err) {
			return Snapshot{}, runError(CodeConflict, "accept", runID, "run identity or acceptance key already exists", false, err)
		}
		return Snapshot{}, classifyStoreError("accept", "persist durable acceptance failed", err)
	}
	if input.OperationAlias != "" {
		if len(input.OperationAlias) > MaxSafeValueBytes || strings.ContainsAny(input.OperationAlias, "\x00\r\n") {
			return Snapshot{}, invalidField("operation_alias", "must be a bounded opaque value")
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO operation_aliases (alias_id, run_id, alias_kind, created_at) VALUES (?, ?, 'operation', ?)`, input.OperationAlias, string(runID), formatTime(now)); err != nil {
			if isConstraint(err) {
				return Snapshot{}, runError(CodeConflict, "accept_alias", runID, "operation alias already exists", false, err)
			}
			return Snapshot{}, classifyStoreError("accept_alias", "persist operation alias failed", err)
		}
	}
	snapshot, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		return Snapshot{}, err
	}
	if err := snapshot.Validate(); err != nil {
		return Snapshot{}, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, classifyStoreError("accept_commit", "commit durable acceptance failed", err)
	}
	r.log(ctx, LogInfo, "run accepted",
		LogField{Key: "run_id", Value: string(runID)}, LogField{Key: "target_kind", Value: input.Target.Kind},
		LogField{Key: "operation", Value: input.Target.Operation}, LogField{Key: "lifecycle", Value: string(snapshot.Lifecycle)})
	return snapshot, nil
}

func (r *SQLiteRepository) ResolveOperationAlias(ctx context.Context, alias string) (Snapshot, error) {
	if strings.TrimSpace(alias) == "" || len(alias) > MaxSafeValueBytes || strings.ContainsAny(alias, "\x00\r\n") {
		return Snapshot{}, invalidField("operation_alias", "must be a bounded opaque value")
	}
	var runID RunID
	if err := r.db.QueryRowContext(ctx, `SELECT run_id FROM operation_aliases WHERE alias_id = ?`, alias).Scan(&runID); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return Snapshot{}, wrapError(CodeNotFound, "resolve_alias", "operation alias is not retained", false, err)
		}
		return Snapshot{}, classifyStoreError("resolve_alias", "resolve operation alias failed", err)
	}
	return r.Snapshot(ctx, runID)
}

func (r *SQLiteRepository) Claim(ctx context.Context, input Claim) (Attempt, Snapshot, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := input.RunID.Validate(); err != nil {
		return Attempt{}, Snapshot{}, err
	}
	if err := input.Owner.Validate(); err != nil {
		return Attempt{}, Snapshot{}, err
	}
	if err := input.Correlation.Validate(); err != nil {
		return Attempt{}, Snapshot{}, err
	}
	if input.Lease <= 0 {
		return Attempt{}, Snapshot{}, invalidField("lease", "must be positive")
	}
	attemptID := input.AttemptID
	var err error
	if attemptID == "" {
		attemptID, err = r.ids.NewAttemptID()
		if err != nil {
			return Attempt{}, Snapshot{}, err
		}
	}
	if err := attemptID.Validate(); err != nil {
		return Attempt{}, Snapshot{}, err
	}
	correlation, err := marshalBounded(input.Correlation, MaxSafeValueBytes*8)
	if err != nil {
		return Attempt{}, Snapshot{}, err
	}
	now := r.now()
	leaseAt := now.Add(input.Lease)
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return Attempt{}, Snapshot{}, ctxErr
		}
		return Attempt{}, Snapshot{}, classifyStoreError("claim_begin", "begin owner claim failed", err)
	}
	defer tx.Rollback()
	var lifecycle string
	var currentAttempt sql.NullString
	if err := tx.QueryRowContext(ctx, `SELECT lifecycle, current_attempt_id FROM runs WHERE run_id = ?`, string(input.RunID)).Scan(&lifecycle, &currentAttempt); err != nil {
		return Attempt{}, Snapshot{}, mapRunLookupError("claim", input.RunID, err)
	}
	state := Lifecycle(lifecycle)
	if state.IsTerminal() {
		return Attempt{}, Snapshot{}, runError(CodeTerminal, "claim", input.RunID, "terminal run cannot be claimed", false, nil)
	}
	if currentAttempt.Valid && currentAttempt.String != "" {
		return Attempt{}, Snapshot{}, runError(CodeConflict, "claim", input.RunID, "run already has a current owner attempt", false, nil)
	}
	nextLifecycle := LifecycleRunning
	if state == LifecycleCancelling {
		nextLifecycle = LifecycleCancelling
	}
	var ordinal, generation uint64
	if err := tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(ordinal), 0) + 1, COALESCE(MAX(fencing_generation), 0) + 1 FROM attempts WHERE run_id = ?`, string(input.RunID)).Scan(&ordinal, &generation); err != nil {
		return Attempt{}, Snapshot{}, classifyStoreError("claim_allocate", "allocate owner fence failed", err)
	}
	_, err = tx.ExecContext(ctx, `
INSERT INTO attempts (
    attempt_id, run_id, ordinal, owner_id, fencing_generation, host_digest, boot_id, pid,
    process_birth_token, claimed_at, heartbeat_at, lease_expires_at, correlation_json
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		string(attemptID), string(input.RunID), ordinal, input.Owner.ID, generation,
		input.Owner.Process.HostDigest, input.Owner.Process.BootID, input.Owner.Process.PID,
		input.Owner.Process.BirthToken, formatTime(now), formatTime(now), formatTime(leaseAt), correlation)
	if err != nil {
		if isConstraint(err) {
			return Attempt{}, Snapshot{}, runError(CodeConflict, "claim", input.RunID, "attempt identity or fence already exists", false, err)
		}
		return Attempt{}, Snapshot{}, classifyStoreError("claim", "persist owner claim failed", err)
	}

package runcontrol

import (
	"context"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

func (r *SQLiteRepository) Heartbeat(ctx context.Context, fence Fence, lease time.Duration) (Snapshot, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := fence.Validate(); err != nil {
		return Snapshot{}, err
	}
	if lease <= 0 {
		return Snapshot{}, invalidField("lease", "must be positive")
	}
	if usage, err := r.storageBytes(); err != nil {
		return Snapshot{}, err
	} else if usage >= r.retention.HardQuotaBytes {
		return Snapshot{}, runError(CodeQuota, "heartbeat_quota", fence.RunID, "hard quota requires the owner to stop active work", true, nil)
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_begin", "begin owner heartbeat failed", err)
	}
	defer tx.Rollback()
	if err := verifyFence(ctx, tx, fence); err != nil {
		return Snapshot{}, err
	}
	result, err := tx.ExecContext(ctx, `
UPDATE attempts SET heartbeat_at = ?, lease_expires_at = ?
WHERE run_id = ? AND attempt_id = ? AND owner_id = ? AND fencing_generation = ? AND outcome IS NULL`,
		formatTime(now), formatTime(now.Add(lease)), string(fence.RunID), string(fence.AttemptID), fence.OwnerID, fence.FencingGeneration)
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat", "persist owner heartbeat failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, runError(CodeStaleFence, "heartbeat", fence.RunID, "owner heartbeat lost its authoritative fence", false, err)
	}
	result, err = tx.ExecContext(ctx, `UPDATE runs SET liveness = ?, updated_at = ? WHERE run_id = ? AND current_attempt_id = ? AND terminal_outcome IS NULL`,
		string(LivenessLive), formatTime(now), string(fence.RunID), string(fence.AttemptID))
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_snapshot", "update heartbeat snapshot failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, runError(CodeStaleFence, "heartbeat", fence.RunID, "run is no longer owned by heartbeat attempt", false, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_commit", "commit owner heartbeat failed", err)
	}
	r.log(ctx, LogDebug, "run owner heartbeat committed",
		LogField{Key: "run_id", Value: string(fence.RunID)}, LogField{Key: "attempt_id", Value: string(fence.AttemptID)},
		LogField{Key: "owner_id", Value: fence.OwnerID}, LogField{Key: "fencing_generation", Value: fmt.Sprint(fence.FencingGeneration)})
	r.metrics.leaseRenewals.Add(1)
	return snapshot, nil
}

func (r *SQLiteRepository) RequestCancellation(ctx context.Context, runID RunID, reason string) (Snapshot, bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := runID.Validate(); err != nil {
		return Snapshot{}, false, err
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > MaxSafeValueBytes || strings.ContainsAny(reason, "\x00\r\n") {
		return Snapshot{}, false, invalidField("cancellation.reason", "must be a bounded canonical reason")
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_begin", "begin cancellation request failed", err)
	}
	defer tx.Rollback()
	current, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if current.Terminal != nil || current.Cancellation.State != CancellationNone {
		if err := tx.Commit(); err != nil {
			return Snapshot{}, false, classifyStoreError("cancel_read_commit", "finish cancellation state read failed", err)
		}
		return current, false, nil
	}
	sequence := current.LastSequence + 1
	payload, err := marshalBounded(map[string]string{"state": string(CancellationRequested), "reason": reason}, MaxSafeValueBytes*2)
	if err != nil {
		return Snapshot{}, false, err
	}
	var attemptValue any
	if current.CurrentAttemptID != "" {
		attemptValue = string(current.CurrentAttemptID)
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, attempt_id, payload_json)
VALUES (?, ?, ?, 'cancellation', ?, ?)`, string(runID), sequence, formatTime(now), attemptValue, payload); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_event", "persist cancellation event failed", err)
	}
	result, err := tx.ExecContext(ctx, `
UPDATE runs SET lifecycle = ?, cancellation_state = ?, cancellation_reason = ?, cancellation_requested_at = ?, updated_at = ?, last_sequence = ?
WHERE run_id = ? AND terminal_outcome IS NULL AND cancellation_state = ? AND last_sequence = ?`,
		string(LifecycleCancelling), string(CancellationRequested), reason, formatTime(now), formatTime(now), sequence,
		string(runID), string(CancellationNone), current.LastSequence)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel", "persist cancellation request failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, false, runError(CodeConflict, "cancel", runID, "cancellation state changed concurrently", true, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_commit", "commit cancellation request failed", err)
	}
	r.notify(runID, sequence)
	r.log(ctx, LogInfo, "run cancellation requested",
		LogField{Key: "run_id", Value: string(runID)}, LogField{Key: "sequence", Value: fmt.Sprint(sequence)},
		LogField{Key: "cancellation_state", Value: string(snapshot.Cancellation.State)}, LogField{Key: "cancellation_reason", Value: reason})
	r.metrics.cancellationRequests.Add(1)
	return snapshot, true, nil
}

func (r *SQLiteRepository) AcknowledgeCancellation(ctx context.Context, fence Fence) (Snapshot, bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := fence.Validate(); err != nil {
		return Snapshot{}, false, err
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_begin", "begin cancellation acknowledgement failed", err)
	}
	defer tx.Rollback()
	if err := verifyFence(ctx, tx, fence); err != nil {
		return Snapshot{}, false, err
	}
	current, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if current.Terminal != nil || current.Cancellation.State == CancellationAcknowledged {
		if err := tx.Commit(); err != nil {
			return Snapshot{}, false, classifyStoreError("cancel_ack_read_commit", "finish cancellation acknowledgement read failed", err)
		}
		return current, false, nil
	}
	if current.Cancellation.State != CancellationRequested {
		return Snapshot{}, false, runError(CodeConflict, "cancel_ack", fence.RunID, "cancellation has not been requested", false, nil)
	}
	sequence := current.LastSequence + 1
	payload, _ := marshalBounded(map[string]string{"state": string(CancellationAcknowledged)}, MaxSafeValueBytes)
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, attempt_id, payload_json)
VALUES (?, ?, ?, 'cancellation', ?, ?)`, string(fence.RunID), sequence, formatTime(now), string(fence.AttemptID), payload); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_event", "persist cancellation acknowledgement event failed", err)
	}
	result, err := tx.ExecContext(ctx, `
UPDATE runs SET cancellation_state = ?, cancellation_acknowledged_at = ?, updated_at = ?, last_sequence = ?
WHERE run_id = ? AND current_attempt_id = ? AND cancellation_state = ? AND terminal_outcome IS NULL AND last_sequence = ?`,
		string(CancellationAcknowledged), formatTime(now), formatTime(now), sequence, string(fence.RunID), string(fence.AttemptID),
		string(CancellationRequested), current.LastSequence)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack", "persist cancellation acknowledgement failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, false, runError(CodeStaleFence, "cancel_ack", fence.RunID, "cancellation acknowledgement lost its fence", false, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_commit", "commit cancellation acknowledgement failed", err)
	}
	r.notify(fence.RunID, sequence)
	r.log(ctx, LogInfo, "run cancellation acknowledged",
		LogField{Key: "run_id", Value: string(fence.RunID)}, LogField{Key: "attempt_id", Value: string(fence.AttemptID)},
		LogField{Key: "sequence", Value: fmt.Sprint(sequence)}, LogField{Key: "cancellation_state", Value: string(snapshot.Cancellation.State)})
	return snapshot, true, nil
}

func (r *SQLiteRepository) List(ctx context.Context, query Query) (Page, error) {
	limit := query.Limit
	if limit == 0 {
		limit = 50
	}
	if limit < 1 || limit > 200 {
		return Page{}, invalidField("query.limit", "must be between 1 and 200")
	}
	clauses := []string{"1=1"}
	args := make([]any, 0, 8)
	if len(query.Lifecycle) > 0 {
		parts := make([]string, 0, len(query.Lifecycle))
		for _, lifecycle := range query.Lifecycle {
			if !lifecycle.IsValid() {
				return Page{}, invalidField("query.lifecycle", "contains an unknown state")
			}
			parts = append(parts, "?")
			args = append(args, string(lifecycle))
		}
		clauses = append(clauses, "lifecycle IN ("+strings.Join(parts, ",")+")")
	}
	for column, value := range map[string]string{
		"target_kind": query.TargetKind, "project_id": query.Project, "sprint_id": query.Sprint, "study_id": query.Study,
	} {
		if value != "" {
			clauses = append(clauses, column+" = ?")
			args = append(args, value)
		}
	}
	if query.After != "" {
		cursor, err := decodeRunCursor(query.After)
		if err != nil {
			return Page{}, err
		}
		clauses = append(clauses, "(updated_at < ? OR (updated_at = ? AND run_id < ?))")
		args = append(args, cursor.UpdatedAt, cursor.UpdatedAt, string(cursor.RunID))
	}
	rows, err := r.db.QueryContext(ctx, `SELECT run_id, updated_at FROM runs WHERE `+strings.Join(clauses, " AND ")+` ORDER BY updated_at DESC, run_id DESC LIMIT ?`, append(args, limit+1)...)
	if err != nil {
		return Page{}, classifyStoreError("list", "list runs failed", err)
	}
	defer rows.Close()
	type listedRun struct {
		id        RunID
		updatedAt string
	}
	listed := make([]listedRun, 0, limit+1)
	for rows.Next() {
		var item listedRun
		if err := rows.Scan(&item.id, &item.updatedAt); err != nil {
			return Page{}, classifyStoreError("list_scan", "decode run list failed", err)
		}
		listed = append(listed, item)
	}
	if err := rows.Err(); err != nil {
		return Page{}, classifyStoreError("list_rows", "read run list failed", err)
	}
	page := Page{Runs: make([]Snapshot, 0, min(limit, len(listed)))}
	if len(listed) > limit {
		page.NextCursor = encodeRunCursor(runCursor{UpdatedAt: listed[limit-1].updatedAt, RunID: listed[limit-1].id})
		listed = listed[:limit]
	}
	for _, item := range listed {
		snapshot, err := r.Snapshot(ctx, item.id)
		if err != nil {
			return Page{}, err
		}
		page.Runs = append(page.Runs, snapshot)
	}
	return page, nil
}

type runCursor struct {
	UpdatedAt string `json:"updated_at"`
	RunID     RunID  `json:"run_id"`
}

func encodeRunCursor(cursor runCursor) string {
	encoded, _ := json.Marshal(cursor)
	return base64.RawURLEncoding.EncodeToString(encoded)
}

func decodeRunCursor(value string) (runCursor, error) {
	encoded, err := base64.RawURLEncoding.DecodeString(value)
	if err != nil || len(encoded) > 1024 {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	var cursor runCursor
	if err := json.Unmarshal(encoded, &cursor); err != nil || cursor.UpdatedAt == "" || cursor.RunID.Validate() != nil {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	if _, err := parseTime(cursor.UpdatedAt); err != nil {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	return cursor, nil
}

type reconciliationCandidate struct {
	runID      RunID
	attemptID  AttemptID
	ownerID    string
	generation uint64
	process    ProcessIdentity
}

func (r *SQLiteRepository) Reconcile(ctx context.Context, probe ProcessProbe, opts ReconcileOptions) (ReconcileReport, error) {
	if probe == nil {
		return ReconcileReport{}, invalidField("process_probe", "is required")
	}
	grace := opts.Grace
	if grace == 0 {
		grace = ReconciliationGrace
	}
	if grace < 0 {
		return ReconcileReport{}, invalidField("reconciliation.grace", "must not be negative")
	}
	limit := opts.Limit
	if limit == 0 {
		limit = DefaultReconcileBatch
	}
	if limit < 1 || limit > MaximumReconcileBatch {
		return ReconcileReport{}, invalidField("reconciliation.limit", fmt.Sprintf("must be between 1 and %d", MaximumReconcileBatch))
	}
	report := ReconcileReport{Decisions: make([]ReconcileDecision, 0, limit)}
	acceptedPredicate, acceptedArgs := r.expiredTimestampPredicate("accepted_at", grace)
	unclaimedRows, err := r.db.QueryContext(ctx, `
SELECT run_id FROM runs
WHERE terminal_outcome IS NULL AND current_attempt_id IS NULL AND `+acceptedPredicate+`
ORDER BY accepted_at ASC, run_id ASC LIMIT ?`, append(acceptedArgs, limit)...)
	if err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "scan unclaimed runs failed", err)
	}
	var unclaimed []RunID
	for unclaimedRows.Next() {
		var runID RunID
		if err := unclaimedRows.Scan(&runID); err != nil {
			unclaimedRows.Close()
			return ReconcileReport{}, classifyStoreError("reconcile_scan", "decode unclaimed run failed", err)
		}
		unclaimed = append(unclaimed, runID)
	}
	if err := unclaimedRows.Close(); err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "close unclaimed run scan failed", err)
	}
	for _, runID := range unclaimed {
		won, err := r.reconcileUnclaimed(ctx, runID)
		if err != nil {
			return report, err
		}
		if !won {
			continue
		}
		report.Scanned++
		report.Terminal++
		decision := "owner_never_claimed_after_grace"
		candidate := reconciliationCandidate{runID: runID}
		_ = r.recordReconciliation(ctx, candidate, "terminal_proposal", decision)
		report.Decisions = append(report.Decisions, ReconcileDecision{RunID: runID, Action: "terminal_proposal", Decision: decision})
	}
	remaining := limit - report.Scanned
	if remaining == 0 {
		r.finishReconciliationLog(ctx, &report)
		return report, nil
	}
	predicate, predicateArgs := r.expiredLeasePredicate(grace)
	queryArgs := append(predicateArgs, remaining)
	rows, err := r.db.QueryContext(ctx, `
SELECT runs.run_id, attempts.attempt_id, attempts.owner_id, attempts.fencing_generation,
       attempts.host_digest, attempts.boot_id, attempts.pid, attempts.process_birth_token
FROM runs JOIN attempts ON attempts.attempt_id = runs.current_attempt_id
WHERE runs.terminal_outcome IS NULL AND `+predicate+`
ORDER BY attempts.lease_expires_at ASC, runs.run_id ASC LIMIT ?`, queryArgs...)
	if err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "scan expired run owners failed", err)
	}
	var candidates []reconciliationCandidate
	for rows.Next() {
		var candidate reconciliationCandidate
		if err := rows.Scan(&candidate.runID, &candidate.attemptID, &candidate.ownerID, &candidate.generation,
			&candidate.process.HostDigest, &candidate.process.BootID, &candidate.process.PID, &candidate.process.BirthToken); err != nil {
			rows.Close()
			return ReconcileReport{}, classifyStoreError("reconcile_scan", "decode expired run owner failed", err)
		}
		candidates = append(candidates, candidate)
	}
	if err := rows.Close(); err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "close expired owner scan failed", err)
	}
	report.Scanned += len(candidates)
	for _, candidate := range candidates {
		observed, probeErr := probe.Probe(ctx, candidate.process.PID)
		decision, outcome := reconcileProcessDecision(candidate.process, observed, probeErr)
		action := "terminal_proposal"
		if outcome == "" {
			action = "mark_stalled"
			if err := r.markStalled(ctx, candidate); err != nil {
				if errors.Is(err, ErrTerminal) || errors.Is(err, ErrStaleFence) {
					continue
				}
				return report, err
			}
			report.Stalled++
		} else {
			fence := Fence{RunID: candidate.runID, AttemptID: candidate.attemptID, OwnerID: candidate.ownerID, FencingGeneration: candidate.generation}
			_, won, err := r.ProposeTerminal(ctx, fence, TerminalProposal{Outcome: outcome, Reason: decision, ProposedBy: "reconciler"})
			if err != nil && !errors.Is(err, ErrTerminal) && !errors.Is(err, ErrStaleFence) {
				return report, err
			}
			if won {
				report.Terminal++
				if outcome == TerminalCleanupUncertain {
					report.Uncertain++
				}
			}
		}
		_ = r.recordReconciliation(ctx, candidate, action, decision)
		report.Decisions = append(report.Decisions, ReconcileDecision{RunID: candidate.runID, AttemptID: candidate.attemptID, Action: action, Decision: decision})
	}
	r.finishReconciliationLog(ctx, &report)
	return report, nil
}

func (r *SQLiteRepository) finishReconciliationLog(ctx context.Context, report *ReconcileReport) {
	r.log(ctx, LogInfo, "run reconciliation completed",
		LogField{Key: "reconciliation_scanned", Value: fmt.Sprint(report.Scanned)},
		LogField{Key: "reconciliation_stalled", Value: fmt.Sprint(report.Stalled)},
		LogField{Key: "reconciliation_terminal", Value: fmt.Sprint(report.Terminal)},
		LogField{Key: "reconciliation_uncertain", Value: fmt.Sprint(report.Uncertain)})
	r.metrics.reconciliations.Add(1)
}

func (r *SQLiteRepository) reconcileUnclaimed(ctx context.Context, runID RunID) (wonResult bool, resultErr error) {
	metricStarted := time.Now()
	defer func() { r.metrics.terminal.observe(metricStarted, resultErr) }()
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_begin", "begin unclaimed reconciliation failed", err)
	}
	defer tx.Rollback()
	current, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	if current.Terminal != nil || current.CurrentAttemptID != "" {
		return false, nil
	}
	sequence := current.LastSequence + 1
	reason := "owner_never_claimed_after_grace"
	payload, err := marshalBounded(map[string]string{"outcome": string(TerminalInterrupted), "reason": reason}, MaxSafeValueBytes*2)
	if err != nil {
		return false, err
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, payload_json)
VALUES (?, ?, ?, 'terminal', ?)`, string(runID), sequence, formatTime(now), payload); err != nil {
		return false, classifyStoreError("reconcile_unclaimed_event", "persist unclaimed terminal event failed", err)
	}
	result, err := tx.ExecContext(ctx, `UPDATE runs SET lifecycle = ?, liveness = ?, finished_at = ?, updated_at = ?, last_sequence = ?,
terminal_outcome = ?, terminal_reason = ?, terminal_at = ?, terminal_proposed_by = 'reconciler'
WHERE run_id = ? AND current_attempt_id IS NULL AND terminal_outcome IS NULL`,
		string(LifecycleInterrupted), string(LivenessTerminal), formatTime(now), formatTime(now), sequence,
		string(TerminalInterrupted), reason, formatTime(now), string(runID))
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_cas", "persist unclaimed terminal state failed", err)
	}
	changed, err := result.RowsAffected()
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_cas", "inspect unclaimed terminal state failed", err)
	}
	if changed != 1 {
		return false, nil
	}
	if err := tx.Commit(); err != nil {
		return false, classifyStoreError("reconcile_unclaimed_commit", "commit unclaimed reconciliation failed", err)
	}
	r.notify(runID, sequence)
	r.log(ctx, LogInfo, "unclaimed run reconciled",
		LogField{Key: "run_id", Value: string(runID)}, LogField{Key: "sequence", Value: fmt.Sprint(sequence)},
		LogField{Key: "terminal_outcome", Value: string(TerminalInterrupted)})
	return true, nil
}

func reconcileProcessDecision(expected, observed ProcessIdentity, probeErr error) (string, TerminalOutcome) {
	if errors.Is(probeErr, ErrProcessNotFound) {
		return "owner_process_missing_after_grace", TerminalInterrupted
	}
	if probeErr != nil {
		return "owner_process_identity_uncertain_after_grace", TerminalCleanupUncertain
	}
	if expected.HostDigest == "" || expected.BootID == "" || expected.BirthToken == "" || observed.HostDigest == "" || observed.BootID == "" || observed.BirthToken == "" {
		return "owner_process_identity_incomplete_after_grace", TerminalCleanupUncertain
	}
	if expected.HostDigest != observed.HostDigest || expected.BootID != observed.BootID || expected.PID != observed.PID || expected.BirthToken != observed.BirthToken {
		return "owner_process_birth_mismatch_after_grace", TerminalInterrupted
	}
	return "exact_owner_process_still_live_but_lease_expired", ""
}

func (r *SQLiteRepository) markStalled(ctx context.Context, candidate reconciliationCandidate) error {
	result, err := r.db.ExecContext(ctx, `
UPDATE runs SET liveness = ?, updated_at = ?
WHERE run_id = ? AND current_attempt_id = ? AND terminal_outcome IS NULL`,
		string(LivenessStalled), formatTime(r.now()), string(candidate.runID), string(candidate.attemptID))
	if err != nil {
		return classifyStoreError("reconcile_stalled", "persist stalled owner state failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return runError(CodeStaleFence, "reconcile_stalled", candidate.runID, "owner changed during reconciliation", false, err)
	}
	return nil
}

func (r *SQLiteRepository) recordReconciliation(ctx context.Context, candidate reconciliationCandidate, action, decision string) error {
	evidenceClass := "safe_identity_only"
	if candidate.attemptID == "" {
		evidenceClass = "acceptance_timestamp_only"
	}
	evidence, _ := json.Marshal(map[string]string{"evidence": evidenceClass})
	var attempt any
	if candidate.attemptID != "" {
		attempt = string(candidate.attemptID)
	}
	_, err := r.db.ExecContext(ctx, `INSERT INTO reconciliation_log (run_id, attempt_id, observed_at, action, decision, evidence_json) VALUES (?, ?, ?, ?, ?, ?)`,
		string(candidate.runID), attempt, formatTime(r.now()), action, decision, string(evidence))
	if err != nil {
		return classifyStoreError("reconcile_log", "persist reconciliation evidence failed", err)
	}
	return nil
}

// ReconciliationEvidence returns newest-first safe reconciliation facts for a
// bounded support export. The stored evidence payload is deliberately reduced
// to its allowlisted classification rather than exposed as arbitrary JSON.
func (r *SQLiteRepository) ReconciliationEvidence(ctx context.Context, limit int) ([]ReconciliationEvidence, error) {
	if limit < 1 || limit > 200 {
		return nil, invalidField("reconciliation_evidence.limit", "must be between 1 and 200")
	}
	rows, err := r.db.QueryContext(ctx, `
SELECT run_id, attempt_id, observed_at, action, decision, evidence_json
FROM reconciliation_log ORDER BY observed_at DESC, id DESC LIMIT ?`, limit)
	if err != nil {
		return nil, classifyStoreError("reconciliation_evidence", "read reconciliation evidence failed", err)
	}
	defer rows.Close()
	result := make([]ReconciliationEvidence, 0, limit)
	for rows.Next() {
		var item ReconciliationEvidence
		var attempt sql.NullString
		var observed, encodedEvidence string
		if err := rows.Scan(&item.RunID, &attempt, &observed, &item.Action, &item.Decision, &encodedEvidence); err != nil {
			return nil, classifyStoreError("reconciliation_evidence", "decode reconciliation evidence failed", err)
		}
		item.AttemptID = AttemptID(attempt.String)
		item.ObservedAt, err = parseTime(observed)
		if err != nil {
			return nil, err
		}
		var stored map[string]string
		if json.Unmarshal([]byte(encodedEvidence), &stored) == nil {
			switch stored["evidence"] {
			case "safe_identity_only", "acceptance_timestamp_only":
				item.Evidence = stored["evidence"]
			}
		}
		if item.Evidence == "" {
			item.Evidence = "omitted"
		}
		result = append(result, item)
	}
	if err := rows.Err(); err != nil {
		return nil, classifyStoreError("reconciliation_evidence", "read reconciliation evidence failed", err)
	}
	return result, nil
}

